-- ACE demonstration question bank.
--
-- These items are synthetic educational examples, not official PNA questions and
-- not a substitute for the linked guidance.  The explicit metadata keeps that
-- distinction queryable even when the presentation layer changes.
alter table questions add column content_origin varchar(30) default 'DEMONSTRATION' not null;
alter table questions add column review_status varchar(40) default 'REQUIRES_CLINICAL_REVIEW' not null;
alter table questions add column provenance_note varchar(800)
    default 'Conteúdo demonstrativo ACE; confirmar a formulação, a resposta e a atualização da fonte antes de utilização formativa.' not null;

alter table questions add constraint chk_questions_correct_index
    check (correct_index between 0 and 3);
alter table questions add constraint chk_questions_content_origin
    check (content_origin in ('DEMONSTRATION', 'CURATED', 'INGESTED'));
alter table questions add constraint chk_questions_review_status
    check (review_status in ('REQUIRES_CLINICAL_REVIEW', 'CLINICALLY_REVIEWED'));

create index idx_questions_review_status on questions(review_status);

-- The original prototype items are synthetic too; do not present them as
-- clinically reviewed merely because they pre-date the provenance columns.
update questions
set status = 'Demonstração',
    content_origin = 'DEMONSTRATION',
    review_status = 'REQUIRES_CLINICAL_REVIEW',
    provenance_note = 'Conteúdo demonstrativo ACE; confirmar a formulação, a resposta e a atualização da fonte antes de utilização formativa.';

-- Avoid a positional cue in the ten legacy examples as well.  Together with
-- the inserts below this leaves exactly 50 correct answers at each index.
update questions set options_text = 'Angio-TC coronária|Ecocardiograma transtorácico|Prova de esforço|Holter de 24 horas', correct_index = 1 where id = 'q-001';
update questions set options_text = 'Antibiótico endovenoso|Salbutamol nebulizado|Dexametasona oral|Intubação imediata', correct_index = 2 where id = 'q-002';
update questions set options_text = 'Colecistite aguda|Diverticulite|Pancreatite aguda|Isquemia mesentérica aguda', correct_index = 3 where id = 'q-003';
update questions set options_text = 'Tratar a hipertensão grave e prevenir convulsões|Aguardar proteinúria de 24 horas|Induzir o parto sem estabilização|Reavaliar em consulta dentro de uma semana', correct_index = 0 where id = 'q-004';
update questions set options_text = 'Iniciar psicoterapia e rever em um mês|Avaliação urgente de risco e garantia de segurança|Recomendar exercício e higiene do sono|Pedir apenas análises gerais', correct_index = 1 where id = 'q-005';
update questions set options_text = 'Diabetes insípida|Hiperaldosteronismo primário|Síndrome de secreção inapropriada de ADH|Polidipsia primária', correct_index = 2 where id = 'q-006';
update questions set options_text = 'Oxigénio de alto débito isolado|Intubação imediata em todos os casos|Nenhum suporte ventilatório|Ventilação não invasiva', correct_index = 3 where id = 'q-007';
update questions set options_text = 'Identificação precoce e intervenção específica segundo o agente|Antibiótico universal no terceiro trimestre|Cesariana eletiva em todas as situações|Suspensão universal da amamentação', correct_index = 0 where id = 'q-008';
update questions set options_text = 'Ressonância magnética|Ecografia FAST|Colonoscopia|Cintigrafia', correct_index = 1 where id = 'q-009';
update questions set options_text = 'Perturbação obsessivo-compulsiva|Distimia|Perturbação de pânico|Delirium', correct_index = 2 where id = 'q-010';

