insert into questions (id, area, topic, difficulty, relevance, competency, stem, options_text, correct_index, explanation, source_name, source_url, status) values
('q-011', 'Medicina', 'Cardiologia', 'Fácil', 'A', 'Diagnóstico', 'Uma pessoa apresenta dor torácica opressiva com 30 minutos de evolução, sudorese e náuseas. Qual é o primeiro exame a realizar?', 'Ecocardiograma transesofágico|Prova de esforço|Holter de 24 horas|Eletrocardiograma de 12 derivações', 3, 'Perante suspeita de síndrome coronária aguda, o eletrocardiograma de 12 derivações deve ser obtido rapidamente para orientar a abordagem inicial.', 'Conteúdo demonstrativo ACE · ESC', 'https://www.escardio.org/Guidelines', 'Demonstração'),
('q-012', 'Medicina', 'Hipertensão arterial', 'Fácil', 'A', 'Diagnóstico', 'Uma pessoa sem sintomas tem valores elevados de pressão arterial em duas medições na consulta. Qual é a melhor forma de confirmar hipertensão persistente?', 'Medição ambulatória ou domiciliária validada|Radiografia do tórax|Doseamento isolado de troponina|Prova de esforço imediata', 0, 'A confirmação fora do consultório ajuda a excluir efeito de bata branca e caracteriza melhor o perfil tensional.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-orientacoes-e-informacoes/normas-e-circulares-normativas.aspx', 'Demonstração'),
('q-013', 'Medicina', 'Pneumologia', 'Fácil', 'A', 'Diagnóstico', 'Uma pessoa com asma refere pieira episódica e tosse variável. Que achado apoia o diagnóstico?', 'Derrame pleural bilateral|Obstrução expiratória reversível na espirometria|Hipercalcemia persistente|Restrição pulmonar fixa', 1, 'A variabilidade dos sintomas acompanhada de limitação expiratória reversível apoia o diagnóstico de asma.', 'Conteúdo demonstrativo ACE · GINA', 'https://ginasthma.org/gina-reports/', 'Demonstração'),
('q-014', 'Medicina', 'Endocrinologia', 'Fácil', 'A', 'Diagnóstico', 'Uma pessoa apresenta poliúria, polidipsia e glicemia plasmática marcadamente elevada. Qual é a hipótese mais provável?', 'Hipotiroidismo|Insuficiência suprarrenal|Diabetes mellitus|Diabetes insípida nefrogénica', 2, 'Poliúria e polidipsia associadas a hiperglicemia marcada são uma apresentação típica de diabetes mellitus.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas-dqs/normas-clinicas.aspx', 'Demonstração'),
('q-015', 'Medicina', 'Nefrologia', 'Fácil', 'B', 'Diagnóstico', 'Qual é o teste urinário simples usado para rastrear albuminúria numa pessoa com diabetes?', 'Urocultura isolada|Citologia urinária|Clearance da ureia em 24 horas|Rácio albumina-creatinina em amostra ocasional', 3, 'O rácio albumina-creatinina numa amostra de urina é uma forma prática de rastrear e quantificar albuminúria.', 'Conteúdo demonstrativo ACE · KDIGO', 'https://kdigo.org/guidelines/', 'Demonstração'),
('q-016', 'Medicina', 'Gastrenterologia', 'Fácil', 'A', 'Gestão do doente', 'Uma pessoa com hematemeses apresenta hipotensão e taquicardia. Qual é a prioridade inicial?', 'Estabilização hemodinâmica e acesso venoso|Colonoscopia eletiva|Teste respiratório para Helicobacter pylori|Dieta sem glúten', 0, 'Na hemorragia digestiva com instabilidade, a avaliação ABC e a ressuscitação precedem a investigação definitiva.', 'Conteúdo demonstrativo ACE · ESGE', 'https://www.esge.com/esge-guidelines/', 'Demonstração'),
('q-017', 'Medicina', 'Neurologia', 'Fácil', 'A', 'Diagnóstico', 'Uma pessoa desenvolve subitamente afasia e hemiparesia direita. Qual é a hipótese que deve ser priorizada?', 'Polineuropatia crónica|Acidente vascular cerebral agudo|Miopatia inflamatória|Doença de Parkinson', 1, 'Um défice neurológico focal súbito deve ser tratado como possível acidente vascular cerebral até prova em contrário.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas-dqs/normas-clinicas.aspx', 'Demonstração'),
('q-018', 'Medicina', 'Infeciologia', 'Fácil', 'A', 'Prevenção', 'Qual é a medida isolada mais importante para reduzir a transmissão cruzada de microrganismos nos cuidados de saúde?', 'Radiografia anual do tórax|Uso universal de antibiótico|Higiene adequada das mãos|Isolamento de todos os doentes', 2, 'A higiene das mãos nos momentos indicados é central na prevenção da transmissão associada aos cuidados de saúde.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas/normas-organizacionais.aspx', 'Demonstração'),
('q-019', 'Medicina', 'Hematologia', 'Fácil', 'B', 'Diagnóstico', 'Uma pessoa com fadiga apresenta hemoglobina baixa, volume globular médio reduzido e ferritina baixa. Qual é o diagnóstico mais provável?', 'Anemia megaloblástica|Esferocitose hereditária|Policitemia vera|Anemia por deficiência de ferro', 3, 'Microcitose com ferritina baixa é compatível com deficiência de ferro, devendo depois procurar-se a causa.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-020', 'Medicina', 'Reumatologia', 'Fácil', 'B', 'Diagnóstico', 'Dor articular com rigidez matinal prolongada e tumefação simétrica das pequenas articulações sugere sobretudo que doença?', 'Artrite reumatoide|Osteoartrose mecânica|Gota podágrica isolada|Fibromialgia', 0, 'O padrão inflamatório, simétrico e envolvendo pequenas articulações é típico de artrite reumatoide.', 'Conteúdo demonstrativo ACE · EULAR', 'https://www.eular.org/recommendations-home', 'Demonstração'),
('q-021', 'Medicina', 'Dermatologia', 'Fácil', 'B', 'Diagnóstico', 'Uma placa eritematosa bem delimitada, coberta por escama prateada numa superfície extensora, é mais compatível com que diagnóstico?', 'Urticária aguda|Psoríase em placas|Celulite bacteriana|Herpes zoster', 1, 'Placas bem delimitadas com escama prateada em superfícies extensoras constituem uma apresentação clássica de psoríase.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-022', 'Medicina', 'Geriatria', 'Fácil', 'A', 'Diagnóstico', 'Num idoso hospitalizado, uma alteração aguda e flutuante da atenção e da consciência sugere que síndrome?', 'Demência estável|Perturbação de personalidade|Delirium|Afasia progressiva primária', 2, 'O início agudo, curso flutuante e défice de atenção caracterizam delirium e exigem procura de causas precipitantes.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-023', 'Medicina', 'Farmacologia', 'Fácil', 'A', 'Gestão do doente', 'Antes de prescrever um novo medicamento, qual é a ação que melhor reduz erros evitáveis?', 'Assumir que a lista antiga está correta|Omitir produtos sem receita|Escolher sempre a dose máxima|Reconciliar medicação, alergias e função renal', 3, 'A reconciliação da medicação e a avaliação de alergias e função renal reduzem interações, duplicações e doses inadequadas.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas/normas-organizacionais.aspx', 'Demonstração'),
('q-024', 'Medicina', 'Cardiologia', 'Média', 'A', 'Gestão do doente', 'Uma pessoa com fibrilhação auricular não valvular tem risco tromboembólico elevado e baixo risco hemorrágico. Que estratégia deve ser ponderada?', 'Anticoagulação oral|Apenas ácido acetilsalicílico em todos os casos|Suspender toda a terapêutica antitrombótica|Cardioversão sem avaliar duração', 0, 'A decisão de anticoagular deve basear-se no risco tromboembólico e hemorrágico, com preferência por uma estratégia individualizada.', 'Conteúdo demonstrativo ACE · ESC', 'https://www.escardio.org/Guidelines', 'Demonstração'),
('q-025', 'Medicina', 'Pneumologia', 'Média', 'A', 'Gestão do doente', 'Numa exacerbação de DPOC com hipoxemia, qual é o objetivo da oxigenoterapia controlada em vez de oxigénio indiscriminado?', 'Normalizar obrigatoriamente a saturação para 100%|Corrigir hipoxemia evitando agravamento de retenção de dióxido de carbono|Substituir broncodilatadores|Evitar qualquer gasometria', 1, 'A oxigenoterapia deve ser titulada e monitorizada, sobretudo quando existe risco de insuficiência respiratória hipercápnica.', 'Conteúdo demonstrativo ACE · GOLD', 'https://goldcopd.org/', 'Demonstração'),
('q-026', 'Medicina', 'Endocrinologia', 'Média', 'A', 'Gestão do doente', 'Uma pessoa com diabetes, vómitos, dor abdominal, hiperglicemia, cetonemia e acidose metabólica necessita prioritariamente de quê?', 'Restrição total de fluidos|Bicarbonato em todos os casos|Fluidos, insulina e vigilância do potássio|Alta com antidiabético oral', 2, 'A cetoacidose diabética exige reposição volémica, insulina e monitorização estreita do potássio e da causa precipitante.', 'Conteúdo demonstrativo ACE · ADA', 'https://professional.diabetes.org/standards-of-care', 'Demonstração'),
('q-027', 'Medicina', 'Nefrologia', 'Média', 'A', 'Mecanismos da doença', 'Na lesão renal aguda pré-renal por hipovolemia, que alteração fisiológica é esperada inicialmente?', 'Glicosúria maciça obrigatória|Poliúria por falta de ADH|Proteinúria nefrótica universal|Aumento da reabsorção renal de sódio e água', 3, 'A redução da perfusão ativa mecanismos de retenção de sódio e água enquanto a estrutura tubular se mantém preservada.', 'Conteúdo demonstrativo ACE · KDIGO', 'https://kdigo.org/guidelines/', 'Demonstração'),
('q-028', 'Medicina', 'Gastrenterologia', 'Média', 'B', 'Diagnóstico', 'Uma pessoa tem dor epigástrica irradiada para o dorso e lipase superior a três vezes o limite normal. Qual é o diagnóstico mais provável?', 'Pancreatite aguda|Apendicite aguda|Colite ulcerosa|Hepatite autoimune', 0, 'Dor típica associada a elevação significativa de lipase cumpre critérios habituais para pancreatite aguda.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-029', 'Medicina', 'Neurologia', 'Média', 'A', 'Gestão do doente', 'Uma pessoa apresenta crise tónico-clónica que persiste há mais de cinco minutos. Qual é a abordagem inicial apropriada?', 'Aguardar espontaneamente por uma hora|Suporte ABC e benzodiazepina de primeira linha|Realizar punção lombar antes de tratar|Administrar antipsicótico oral', 1, 'Uma crise prolongada deve ser tratada como estado de mal epilético, com estabilização e terapêutica anticonvulsivante imediata.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-030', 'Medicina', 'Infeciologia', 'Média', 'A', 'Gestão do doente', 'Uma pessoa com febre, hipotensão, confusão e suspeita de infeção apresenta sinais de hipoperfusão. Qual é a prioridade?', 'Aguardar cultura positiva antes de agir|Prescrever apenas antipirético|Reconhecer sépsis e iniciar avaliação e tratamento urgentes|Adiar fluidos até ao dia seguinte', 2, 'Sépsis com disfunção orgânica requer colheitas adequadas sem atrasar ressuscitação e antimicrobianos quando indicados.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-031', 'Medicina', 'Hematologia', 'Média', 'B', 'Diagnóstico', 'Trombocitopenia, anemia hemolítica microangiopática, alteração neurológica e renal levantam suspeita de quê?', 'Anemia ferropénica isolada|Hemofilia A|Trombocitose essencial|Púrpura trombótica trombocitopénica', 3, 'A associação de trombocitopenia e hemólise microangiopática, com possível envolvimento orgânico, exige avaliação urgente para PTT.', 'Conteúdo demonstrativo ACE · ASH', 'https://www.hematology.org/education/clinicians/guidelines-and-quality-care', 'Demonstração'),
('q-032', 'Medicina', 'Oncologia', 'Média', 'B', 'Prevenção', 'Qual é o princípio mais importante antes de propor um rastreio oncológico a uma pessoa assintomática?', 'Confirmar elegibilidade, benefícios, riscos e decisão informada|Pedir todos os marcadores tumorais disponíveis|Garantir que um teste positivo é diagnóstico definitivo|Ignorar idade e esperança de vida', 0, 'O rastreio deve seguir programas e recomendações aplicáveis, considerando benefícios, danos e preferências informadas.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-orientacoes-e-informacoes/normas-e-circulares-normativas.aspx', 'Demonstração'),
('q-033', 'Medicina', 'Reumatologia', 'Média', 'B', 'Gestão do doente', 'Uma pessoa com monoartrite aguda, febre e articulação muito dolorosa deve realizar prioritariamente que exame?', 'Densitometria óssea|Artrocentese com análise do líquido sinovial|Eletromiografia|Biópsia muscular', 1, 'Perante suspeita de artrite séptica, a colheita urgente de líquido sinovial orienta diagnóstico e tratamento.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-034', 'Medicina', 'Medicina intensiva', 'Média', 'A', 'Gestão do doente', 'Após administrar fluidos a uma pessoa em choque, que parâmetro ajuda a avaliar resposta de perfusão de forma seriada?', 'Apenas temperatura axilar|Somente peso corporal anual|Estado mental, diurese, pressão arterial e lactato em conjunto|Uma radiografia da mão', 2, 'A resposta deve ser avaliada clinicamente e com marcadores seriados de perfusão, evitando depender de um único valor.', 'Conteúdo demonstrativo ACE · ESICM', 'https://www.esicm.org/resources/guidelines-consensus-statements/', 'Demonstração'),
('q-035', 'Medicina', 'Alergologia', 'Média', 'A', 'Gestão do doente', 'Após contacto com alergénio, uma pessoa apresenta urticária, broncospasmo e hipotensão. Qual é o tratamento de primeira linha?', 'Anti-histamínico oral isolado|Corticosteroide tópico|Antibiótico endovenoso|Adrenalina intramuscular', 3, 'A adrenalina intramuscular é o tratamento de primeira linha da anafilaxia e não deve ser atrasada por terapêuticas adjuvantes.', 'Conteúdo demonstrativo ACE · ERC', 'https://www.erc.edu/science-research/guidelines', 'Demonstração'),
('q-036', 'Medicina', 'Cardiologia', 'Difícil', 'A', 'Diagnóstico', 'Uma pessoa com dor torácica súbita, assimetria de pulsos e novo sopro diastólico apresenta pressão arterial estável. Qual é o exame imagiológico prioritário se disponível?', 'Angio-TC da aorta|Prova de esforço|Cintigrafia de perfusão miocárdica|Holter de sete dias', 0, 'A suspeita de síndrome aórtica aguda exige imagem urgente da aorta; em estabilidade, a angio-TC é habitualmente o exame inicial.', 'Conteúdo demonstrativo ACE · ESC', 'https://www.escardio.org/Guidelines', 'Demonstração'),
('q-037', 'Medicina', 'Pneumologia', 'Difícil', 'A', 'Diagnóstico', 'Uma pessoa com dispneia súbita, taquicardia e probabilidade clínica elevada de embolia pulmonar está hemodinamicamente estável. Qual é o exame confirmatório habitual?', 'Espirometria simples|Angio-TC pulmonar|Broncoscopia rígida|Radiografia das mãos', 1, 'Em estabilidade e sem contraindicação, a angio-TC pulmonar é o exame de imagem habitual para confirmar embolia pulmonar.', 'Conteúdo demonstrativo ACE · ESC', 'https://www.escardio.org/Guidelines', 'Demonstração'),
('q-038', 'Medicina', 'Endocrinologia', 'Difícil', 'B', 'Diagnóstico', 'Hipotensão, hiponatremia, hipercaliemia, hipoglicemia e hiperpigmentação sugerem insuficiência de que órgão?', 'Hipófise posterior isolada|Paratiroides|Córtex suprarrenal|Pâncreas exócrino', 2, 'O défice primário de cortisol e aldosterona pode causar este padrão clínico e laboratorial.', 'Conteúdo demonstrativo ACE · ESE', 'https://www.ese-hormones.org/publications/guidelines/', 'Demonstração'),
('q-039', 'Medicina', 'Nefrologia', 'Difícil', 'B', 'Gestão do doente', 'Uma pessoa com insuficiência renal apresenta hipercaliemia grave e alterações eletrocardiográficas. Qual é a intervenção imediata para estabilizar o miocárdio?', 'Resina oral como única medida|Restrição proteica isolada|Furosemida oral em baixa dose apenas|Cálcio intravenoso', 3, 'O cálcio intravenoso estabiliza a membrana cardíaca; outras medidas são necessárias para deslocar e remover potássio.', 'Conteúdo demonstrativo ACE · KDIGO', 'https://kdigo.org/guidelines/', 'Demonstração'),
('q-040', 'Medicina', 'Gastrenterologia', 'Difícil', 'B', 'Gestão do doente', 'Uma pessoa com cirrose apresenta hematemeses volumosas. Além da ressuscitação e endoscopia urgente, que estratégia farmacológica empírica é apropriada?', 'Fármaco vasoativo e profilaxia antibiótica|Anticoagulação plena imediata|Anti-inflamatório não esteroide|Laxante osmótico isolado', 0, 'Na suspeita de hemorragia varicosa, recomenda-se terapêutica vasoativa precoce e profilaxia antibiótica, além do controlo endoscópico.', 'Conteúdo demonstrativo ACE · EASL', 'https://easl.eu/publication-type/clinical-practice-guidelines/', 'Demonstração'),
('q-041', 'Medicina', 'Neurologia', 'Difícil', 'A', 'Diagnóstico', 'Fraqueza ascendente simétrica, arreflexia e parestesias após infeção respiratória sugerem que síndrome?', 'Miastenia ocular isolada|Síndrome de Guillain-Barré|Esclerose lateral amiotrófica|Acidente vascular lacunar', 1, 'A polirradiculoneuropatia inflamatória aguda apresenta frequentemente fraqueza ascendente e arreflexia após infeção.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-042', 'Medicina', 'Infeciologia', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa com febre, rigidez da nuca, confusão e púrpura tem suspeita de meningite bacteriana. Qual é o princípio de atuação?', 'Aguardar sempre por punção lombar se houver instabilidade|Tratar apenas com antipirético|Colher culturas quando possível e iniciar antibiótico urgente sem atraso indevido|Dar alta após TC normal', 2, 'A suspeita de meningite bacteriana exige antimicrobianos precoces; exames não devem atrasar tratamento quando há risco.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas-dqs/normas-clinicas.aspx', 'Demonstração'),
('q-043', 'Medicina', 'Hematologia', 'Difícil', 'B', 'Gestão do doente', 'Uma pessoa em quimioterapia apresenta febre e neutropenia profunda. Qual é a conduta inicial?', 'Aguardar recuperação espontânea dos neutrófilos|Administrar vacina viva|Prescrever ferro oral|Antibioterapia empírica urgente após avaliação e culturas', 3, 'A neutropenia febril é uma emergência; a antibioterapia empírica deve ser iniciada rapidamente após a avaliação inicial.', 'Conteúdo demonstrativo ACE · ESMO', 'https://www.esmo.org/guidelines', 'Demonstração'),
('q-044', 'Medicina', 'Reumatologia', 'Difícil', 'B', 'Diagnóstico', 'Uma pessoa jovem apresenta hemoptises, deterioração renal rápida e sedimento urinário ativo. Qual é a prioridade diagnóstica?', 'Investigar síndrome pulmão-rim por vasculite ou doença anti-membrana basal|Assumir bronquite simples|Pedir apenas teste alérgico cutâneo|Aguardar seis meses', 0, 'Hemorragia alveolar e glomerulonefrite rapidamente progressiva configuram uma síndrome pulmão-rim potencialmente fatal.', 'Conteúdo demonstrativo ACE · EULAR', 'https://www.eular.org/recommendations-home', 'Demonstração'),
('q-045', 'Medicina', 'Medicina intensiva', 'Difícil', 'A', 'Mecanismos da doença', 'Numa pessoa ventilada com hipoxemia grave e infiltrados bilaterais sem explicação cardíaca dominante, que síndrome deve ser considerada?', 'Derrame pleural simples|Síndrome de dificuldade respiratória aguda|Asma intermitente|Apneia obstrutiva do sono', 1, 'Hipoxemia aguda com opacidades bilaterais e edema não explicado sobretudo por falência cardíaca sugere SDRA.', 'Conteúdo demonstrativo ACE · ESICM', 'https://www.esicm.org/resources/guidelines-consensus-statements/', 'Demonstração'),
('q-046', 'Medicina', 'Toxicologia', 'Difícil', 'B', 'Gestão do doente', 'Uma pessoa inconsciente apresenta miose puntiforme e depressão respiratória após exposição desconhecida. Qual é o antídoto a considerar?', 'Flumazenilo em todos os comas|Atropina como única medida|Naloxona|Vitamina K', 2, 'A tríade sugere toxicidade por opioides; suporte ventilatório e naloxona titulada são medidas essenciais.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-047', 'Medicina', 'Metabolismo', 'Difícil', 'B', 'Mecanismos da doença', 'Uma pessoa com vómitos prolongados apresenta pH elevado, bicarbonato elevado e cloro baixo. Qual é a alteração ácido-base primária?', 'Acidose metabólica com anion gap|Acidose respiratória|Alcalose respiratória isolada|Alcalose metabólica', 3, 'A perda de ácido gástrico provoca alcalose metabólica hipoclorémica, frequentemente associada a contração de volume.', 'Conteúdo demonstrativo ACE · KDIGO', 'https://kdigo.org/guidelines/', 'Demonstração');
insert into questions (id, area, topic, difficulty, relevance, competency, stem, options_text, correct_index, explanation, source_name, source_url, status) values
('q-048', 'Pediatria', 'Puericultura', 'Fácil', 'A', 'Prevenção', 'Qual é uma oportunidade essencial em cada consulta de vigilância infantil?', 'Avaliar crescimento, desenvolvimento e vacinação|Pedir TC de corpo inteiro|Prescrever antibiótico preventivo|Restringir atividade física', 0, 'A vigilância infantil integra crescimento, desenvolvimento, imunização, prevenção e aconselhamento familiar.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/pns-e-programas/programas-de-saude-prioritarios/saude-infantil-e-juvenil.aspx', 'Demonstração'),
('q-049', 'Pediatria', 'Gastrenterologia', 'Fácil', 'A', 'Gestão do doente', 'Uma criança com gastroenterite ligeira está alerta e tolera líquidos. Qual é a terapêutica inicial preferida?', 'Jejum durante 24 horas|Solução de reidratação oral em pequenas quantidades frequentes|Antibiótico em todos os casos|Bebida gaseificada sem restrição', 1, 'A reidratação oral é eficaz na desidratação ligeira a moderada e deve ser oferecida de forma fracionada.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-050', 'Pediatria', 'Pneumologia', 'Fácil', 'A', 'Diagnóstico', 'Um lactente apresenta coriza seguida de tosse, taquipneia, sibilos e crepitações na primeira infeção respiratória baixa. Qual é o diagnóstico mais provável?', 'Epiglotite|Fibrose quística|Bronquiolite aguda|Pneumotórax espontâneo', 2, 'A bronquiolite é um diagnóstico clínico típico no lactente com pródromo viral e sinais respiratórios baixos.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng9', 'Demonstração'),
('q-051', 'Pediatria', 'Otorrinolaringologia', 'Fácil', 'B', 'Diagnóstico', 'Uma criança com otalgia aguda tem membrana timpânica abaulada e opaca. Qual é o diagnóstico mais provável?', 'Otite externa maligna|Rinite alérgica|Mastoidite crónica|Otite média aguda', 3, 'O abaulamento da membrana timpânica no contexto de sintomas agudos é um achado importante de otite média aguda.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-052', 'Pediatria', 'Crescimento', 'Fácil', 'A', 'Diagnóstico', 'Qual é a melhor forma de interpretar o crescimento de uma criança ao longo do tempo?', 'Traçar medições seriadas em curvas adequadas|Usar apenas um peso isolado|Comparar apenas com irmãos|Ignorar o perímetro cefálico no lactente', 0, 'A trajetória em curvas adequadas à idade e sexo é mais informativa do que uma medição isolada.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/tools/child-growth-standards', 'Demonstração'),
('q-053', 'Pediatria', 'Neonatologia', 'Fácil', 'A', 'Diagnóstico', 'Qual dos seguintes é um sinal de alarme numa icterícia neonatal?', 'Início após o terceiro dia num recém-nascido bem|Aparecimento nas primeiras 24 horas de vida|Melhoria progressiva|Aleitamento eficaz', 1, 'Icterícia nas primeiras 24 horas é patológica até prova em contrário e necessita de avaliação rápida.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg98', 'Demonstração'),
('q-054', 'Pediatria', 'Neurologia', 'Fácil', 'B', 'Gestão do doente', 'Durante uma convulsão febril generalizada que termina espontaneamente, qual é uma medida imediata apropriada?', 'Introduzir um objeto na boca|Conter os membros com força|Colocar a criança em segurança e avaliar via aérea|Administrar antibiótico sem avaliação', 2, 'Deve proteger-se a criança de lesões, garantir via aérea e registar duração, sem colocar objetos na boca.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-055', 'Pediatria', 'Nutrição', 'Fácil', 'B', 'Prevenção', 'Na diversificação alimentar, qual é a recomendação geral mais segura?', 'Oferecer frutos secos inteiros ao lactente|Adicionar sal a todas as refeições|Substituir leite por bebidas açucaradas|Introduzir alimentos adequados à idade mantendo variedade e supervisão', 3, 'A alimentação complementar deve ser progressiva, variada e adaptada ao desenvolvimento, reduzindo riscos de engasgamento.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/health-topics/infant-and-young-child-feeding', 'Demonstração'),
('q-056', 'Pediatria', 'Pneumologia', 'Fácil', 'A', 'Gestão do doente', 'Numa criança com asma que usa inalador pressurizado, que dispositivo melhora habitualmente a deposição do fármaco?', 'Câmara expansora adequada|Sonda nasogástrica|Máscara laríngea em casa|Nebulizador sem indicação em todos os casos', 0, 'A câmara expansora facilita a técnica e melhora a administração de fármacos inalados em idade pediátrica.', 'Conteúdo demonstrativo ACE · GINA', 'https://ginasthma.org/gina-reports/', 'Demonstração'),
('q-057', 'Pediatria', 'Prevenção de acidentes', 'Fácil', 'A', 'Prevenção', 'Qual é a forma mais segura de transportar um lactente num automóvel?', 'Ao colo de um adulto no banco traseiro|Sistema de retenção homologado, adequado ao tamanho e corretamente instalado|No banco dianteiro sem retenção|Deitado no assento com cinto de adulto', 1, 'Um sistema de retenção infantil adequado e bem instalado reduz substancialmente o risco de lesão.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/pns-e-programas/programas-de-saude-prioritarios/saude-infantil-e-juvenil.aspx', 'Demonstração'),
('q-058', 'Pediatria', 'Nefrologia', 'Fácil', 'B', 'Diagnóstico', 'Uma criança com febre sem foco tem leucocitúria. Qual é a colheita necessária antes de iniciar antibiótico, se a situação permitir?', 'Urina recolhida de saco sem confirmação|Citologia urinária|Urocultura por método apropriado|Proteinúria de 24 horas', 2, 'O diagnóstico de infeção urinária requer cultura de uma amostra colhida com técnica que minimize contaminação.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng224', 'Demonstração'),
('q-059', 'Pediatria', 'Dermatologia', 'Fácil', 'B', 'Gestão do doente', 'Uma criança com dermatite atópica ligeira tem pele seca e prurido. Qual é a base do tratamento diário?', 'Antibiótico oral contínuo|Evitar todos os banhos|Corticosteroide sistémico crónico|Emolientes usados regularmente', 3, 'Os emolientes restauram a barreira cutânea e são a base do tratamento, associados a anti-inflamatório tópico quando indicado.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg57', 'Demonstração'),
('q-060', 'Pediatria', 'Neonatologia', 'Média', 'A', 'Gestão do doente', 'Um recém-nascido apresenta má perfusão, instabilidade térmica e dificuldade alimentar. Qual é a atitude mais adequada?', 'Investigar e tratar rapidamente possível sépsis neonatal|Aguardar 48 horas sem observar|Dar apenas solução açucarada|Assumir cólica do lactente', 0, 'A sépsis neonatal pode apresentar sinais inespecíficos e requer avaliação e antibioterapia empírica atempadas quando suspeita.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-061', 'Pediatria', 'Cardiologia', 'Média', 'B', 'Diagnóstico', 'Febre há seis dias, conjuntivite bilateral não purulenta, alterações orais, exantema e edema das extremidades sugerem que doença?', 'Escarlatina isolada|Doença de Kawasaki|Varicela|Eritema infeccioso', 1, 'Febre prolongada associada aos achados mucocutâneos típicos deve levantar suspeita de doença de Kawasaki.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-062', 'Pediatria', 'Endocrinologia', 'Média', 'A', 'Gestão do doente', 'Uma criança com diabetes tipo 1 tem vómitos, respiração profunda, hiperglicemia e cetonemia. Que complicação deve ser assumida?', 'Hipoglicemia assintomática|Diabetes insípida|Cetoacidose diabética|Síndrome nefrótica', 2, 'O conjunto é típico de cetoacidose diabética e exige protocolo pediátrico com fluidos, insulina e monitorização intensiva.', 'Conteúdo demonstrativo ACE · ISPAD', 'https://www.ispad.org/resources/ispad-clinical-practice-consensus-guidelines.html', 'Demonstração'),
('q-063', 'Pediatria', 'Infeciologia', 'Média', 'A', 'Gestão do doente', 'Uma criança febril apresenta petéquias não branqueáveis e aspeto tóxico. Qual é a abordagem correta?', 'Reassurar sem observação|Aplicar apenas creme tópico|Marcar consulta de rotina|Avaliação hospitalar urgente por possível infeção invasiva', 3, 'Exantema não branqueável com doença sistémica pode indicar infeção meningocócica e requer resposta imediata.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng240', 'Demonstração'),
('q-064', 'Pediatria', 'Nefrologia', 'Média', 'B', 'Diagnóstico', 'Edema periorbitário, proteinúria marcada, hipoalbuminemia e hiperlipidemia numa criança sugerem que síndrome?', 'Síndrome nefrótica|Síndrome hemolítico-urémica|Pielonefrite|Diabetes insípida', 0, 'A combinação de proteinúria maciça, hipoalbuminemia e edema define síndrome nefrótica.', 'Conteúdo demonstrativo ACE · KDIGO', 'https://kdigo.org/guidelines/', 'Demonstração'),
('q-065', 'Pediatria', 'Gastrenterologia', 'Média', 'A', 'Diagnóstico', 'Um lactente tem episódios de choro intenso, flexão das pernas, vómitos e fezes com sangue e muco. Qual é a hipótese mais provável?', 'Estenose hipertrófica do piloro|Invaginação intestinal|Refluxo fisiológico|Doença celíaca', 1, 'A dor cólica intermitente e as fezes com sangue e muco são sugestivas de invaginação intestinal.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-066', 'Pediatria', 'Cirurgia pediátrica', 'Média', 'A', 'Diagnóstico', 'Uma criança inicia dor periumbilical que migra para a fossa ilíaca direita, com febre e anorexia. Qual é o diagnóstico provável?', 'Gastroenterite viral simples|Hepatite aguda|Apendicite aguda|Otite média', 2, 'A migração da dor e a localização na fossa ilíaca direita são características de apendicite, embora a apresentação varie com a idade.', 'Conteúdo demonstrativo ACE · WSES', 'https://wjes.biomedcentral.com/', 'Demonstração'),
('q-067', 'Pediatria', 'Hematologia', 'Média', 'B', 'Diagnóstico', 'Uma criança que consome leite em excesso apresenta palidez, microcitose e ferritina baixa. Qual é a causa provável?', 'Défice de vitamina B12|Esferocitose hereditária|Aplasia medular|Deficiência de ferro nutricional', 3, 'Dieta pobre em ferro e consumo excessivo de leite podem contribuir para anemia ferropénica na primeira infância.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-068', 'Pediatria', 'Alergologia', 'Média', 'A', 'Gestão do doente', 'Após ingerir um alimento, uma criança desenvolve urticária generalizada, pieira e prostração. Qual é o tratamento inicial?', 'Adrenalina intramuscular|Anti-histamínico isolado|Antibiótico oral|Salbutamol como única medida', 0, 'O envolvimento de vários sistemas após exposição sugere anafilaxia; adrenalina intramuscular é primeira linha.', 'Conteúdo demonstrativo ACE · ERC', 'https://www.erc.edu/science-research/guidelines', 'Demonstração'),
('q-069', 'Pediatria', 'Pneumologia', 'Média', 'A', 'Diagnóstico', 'Uma criança com febre alta, tosse, taquipneia e crepitações focais tem maior probabilidade de apresentar quê?', 'Rinite alérgica isolada|Pneumonia adquirida na comunidade|Crupe ligeiro|Corpo estranho no ouvido', 1, 'Febre e sinais respiratórios focais com taquipneia são compatíveis com pneumonia, devendo avaliar gravidade e oxigenação.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-070', 'Pediatria', 'Neurologia', 'Média', 'B', 'Diagnóstico', 'Uma criança tem episódios breves de olhar fixo, interrupção da atividade e retoma imediata, várias vezes por dia. Que tipo de crise é provável?', 'Crise tónico-clónica prolongada|Síncope vasovagal típica|Crise de ausência|Tique motor simples', 2, 'Crises de ausência causam interrupções breves da consciência sem período pós-ictal marcado.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng217', 'Demonstração'),
('q-071', 'Pediatria', 'Medicina do adolescente', 'Média', 'B', 'Gestão do doente', 'Numa consulta com adolescente, qual é uma boa prática para facilitar revelação de temas sensíveis?', 'Garantir segredo absoluto mesmo perante risco grave|Falar apenas com os pais|Evitar perguntas sobre segurança|Reservar parte da consulta a sós e explicar limites da confidencialidade', 3, 'Tempo privado e explicação clara da confidencialidade promovem confiança, mantendo exceções quando existe risco relevante.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/health-topics/adolescent-health', 'Demonstração'),
('q-072', 'Pediatria', 'Crescimento', 'Média', 'B', 'Diagnóstico', 'Uma criança cruza dois percentis de peso para baixo. Qual deve ser o primeiro passo?', 'Rever medições, história alimentar, sintomas e contexto familiar|Prescrever hormona do crescimento de imediato|Pedir apenas um cariótipo|Ignorar se a estatura ainda for média', 0, 'A desaceleração ponderal requer confirmação antropométrica e avaliação clínica, nutricional e psicossocial dirigida.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng75', 'Demonstração'),
('q-073', 'Pediatria', 'Cardiologia', 'Média', 'B', 'Diagnóstico', 'Um recém-nascido tem sopro, cianose que não melhora adequadamente com oxigénio e má perfusão. Qual é a prioridade?', 'Reavaliar apenas aos dois anos|Avaliação urgente de cardiopatia congénita crítica|Iniciar ferro oral|Assumir acrocianose fisiológica', 1, 'Cianose persistente e sinais de baixo débito exigem avaliação cardíaca urgente e estabilização especializada.', 'Conteúdo demonstrativo ACE · ESC', 'https://www.escardio.org/Guidelines', 'Demonstração'),
('q-074', 'Pediatria', 'Neonatologia', 'Difícil', 'A', 'Diagnóstico', 'Um recém-nascido apresenta vómito bilioso e distensão abdominal. Que princípio deve orientar a atuação?', 'Considerar refluxo fisiológico sem investigação|Oferecer mais volume por via oral|Assumir obstrução intestinal até prova em contrário e avaliar urgentemente|Dar alta se não houver febre', 2, 'Vómito bilioso no recém-nascido é sinal de alarme para obstrução, incluindo malrotação com volvo.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-075', 'Pediatria', 'Metabolismo', 'Difícil', 'B', 'Diagnóstico', 'Um lactente deteriora após iniciar alimentação, com letargia, vómitos, alcalose respiratória e amónia muito elevada. Que grupo de doenças deve ser considerado?', 'Doença celíaca|Raquitismo nutricional|Anemia ferropénica|Defeito do ciclo da ureia', 3, 'Hiperamoniemia com alcalose respiratória precoce pode indicar defeito do ciclo da ureia e requer tratamento metabólico urgente.', 'Conteúdo demonstrativo ACE · Orphanet', 'https://www.orpha.net/', 'Demonstração'),
('q-076', 'Pediatria', 'Nefrologia', 'Difícil', 'A', 'Diagnóstico', 'Após diarreia sanguinolenta, uma criança desenvolve anemia hemolítica, trombocitopenia e lesão renal aguda. Qual é o diagnóstico provável?', 'Síndrome hemolítico-urémica|Púrpura trombocitopénica imune isolada|Síndrome nefrótica|Glomerulonefrite pós-estreptocócica simples', 0, 'A tríade após doença diarreica é típica de síndrome hemolítico-urémica associada a toxina Shiga.', 'Conteúdo demonstrativo ACE · KDIGO', 'https://kdigo.org/guidelines/', 'Demonstração'),
('q-077', 'Pediatria', 'Pneumologia', 'Difícil', 'A', 'Gestão do doente', 'Uma criança com exacerbação asmática grave fica silenciosa à auscultação, exausta e com alteração da consciência. O que indica este quadro?', 'Melhoria espontânea da obstrução|Insuficiência respiratória iminente e necessidade de ajuda avançada|Ansiedade isolada|Alta segura para casa', 1, 'Tórax silencioso, exaustão e alteração da consciência são sinais de ameaça vital, exigindo escalada imediata.', 'Conteúdo demonstrativo ACE · GINA', 'https://ginasthma.org/gina-reports/', 'Demonstração'),
('q-078', 'Pediatria', 'Medicina intensiva', 'Difícil', 'A', 'Gestão do doente', 'Uma criança com infeção suspeita mantém perfusão deficiente e hipotensão. Qual é a abordagem adequada?', 'Aguardar culturas durante várias horas|Administrar apenas antipirético|Reconhecimento de choque séptico, acesso vascular, fluidos titulados e suporte vasoativo conforme resposta|Evitar monitorização por ser invasiva', 2, 'O choque séptico pediátrico requer tratamento rápido e reavaliações frequentes para evitar excesso ou insuficiência de fluidos.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-079', 'Pediatria', 'Endocrinologia', 'Difícil', 'B', 'Diagnóstico', 'Um recém-nascido com genitália ambígua desenvolve vómitos, hiponatremia, hipercaliemia e choque. Qual é a hipótese prioritária?', 'Hipertiroidismo neonatal|Estenose pilórica|Diabetes mellitus tipo 1|Hiperplasia congénita da suprarrenal com perda de sal', 3, 'A crise perdedora de sal por hiperplasia congénita da suprarrenal é potencialmente fatal e requer tratamento urgente.', 'Conteúdo demonstrativo ACE · ESE', 'https://www.ese-hormones.org/publications/guidelines/', 'Demonstração'),
('q-080', 'Pediatria', 'Proteção da criança', 'Difícil', 'A', 'Gestão do doente', 'Uma criança apresenta equimoses de diferentes idades em áreas protegidas e a história não explica as lesões. Qual é a conduta?', 'Garantir segurança, documentar objetivamente e acionar avaliação multidisciplinar|Confrontar agressivamente a família e dar alta|Ignorar por não haver fratura|Pedir à criança que regresse sozinha', 0, 'Lesões incompatíveis com o desenvolvimento ou história exigem abordagem estruturada centrada na segurança da criança.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/pns-e-programas/programas-de-saude-prioritarios/saude-infantil-e-juvenil.aspx', 'Demonstração'),
('q-081', 'Pediatria', 'Cardiologia', 'Difícil', 'B', 'Diagnóstico', 'Após infeção viral, um adolescente apresenta dor torácica, dispneia, troponina elevada e disfunção ventricular. Qual é a hipótese?', 'Asma induzida por exercício|Miocardite|Refluxo gastroesofágico simples|Costocondrite isolada', 1, 'A lesão miocárdica associada a disfunção ventricular após pródromo viral é sugestiva de miocardite.', 'Conteúdo demonstrativo ACE · ESC', 'https://www.escardio.org/Guidelines', 'Demonstração'),
('q-082', 'Pediatria', 'Infeciologia', 'Difícil', 'A', 'Gestão do doente', 'Uma criança com choque e púrpura rapidamente progressiva tem suspeita de doença meningocócica. Que medida não deve ser atrasada?', 'Confirmação por cultura antes de qualquer tratamento|Biópsia cutânea eletiva|Antibioterapia parentérica e suporte de choque|Alta com vigilância familiar', 2, 'A doença meningocócica invasiva pode progredir rapidamente; tratamento e estabilização têm prioridade sobre confirmação tardia.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng240', 'Demonstração'),
('q-083', 'Pediatria', 'Imunologia', 'Difícil', 'C', 'Diagnóstico', 'Febre persistente, esplenomegalia, citopenias, ferritina muito elevada e disfunção hepática sugerem que síndrome hiperinflamatória?', 'Doença de Kawasaki incompleta isolada|Púrpura de Henoch-Schönlein|Artrite idiopática oligoarticular|Linfo-histiocitose hemofagocítica', 3, 'O conjunto deve levantar suspeita de linfo-histiocitose hemofagocítica, que necessita de confirmação e tratamento especializados urgentes.', 'Conteúdo demonstrativo ACE · Histiocyte Society', 'https://histiocytesociety.org/', 'Demonstração'),
('q-084', 'Pediatria', 'Neurologia', 'Difícil', 'A', 'Gestão do doente', 'Uma criança com cefaleia, vómitos matinais, papiledema e deterioração da consciência deve ser submetida inicialmente a quê?', 'Estabilização e neuroimagem urgente antes de considerar punção lombar|Punção lombar imediata sem imagem|Teste de alergia|Observação domiciliária', 0, 'Sinais de hipertensão intracraniana tornam a punção lombar potencialmente perigosa e indicam avaliação urgente com imagem.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-085', 'Pediatria', 'Metabolismo', 'Difícil', 'B', 'Gestão do doente', 'Um recém-nascido previamente bem apresenta deterioração, acidose metabólica e hipoglicemia após um período de jejum. Qual é a prioridade?', 'Prolongar o jejum para confirmar|Interromper catabolismo com glicose e colher amostras metabólicas urgentes|Administrar apenas água|Aguardar pelo rastreio neonatal sem tratar', 1, 'Uma doença metabólica descompensada exige estabilização, prevenção de catabolismo e colheitas críticas sem atrasar tratamento.', 'Conteúdo demonstrativo ACE · Orphanet', 'https://www.orpha.net/', 'Demonstração');
insert into questions (id, area, topic, difficulty, relevance, competency, stem, options_text, correct_index, explanation, source_name, source_url, status) values
('q-086', 'Cirurgia', 'Princípios cirúrgicos', 'Fácil', 'A', 'Gestão do doente', 'Antes da incisão, que ação da lista de verificação cirúrgica reduz erros de local e procedimento?', 'Confiar apenas na memória do cirurgião|Dispensar marcação do local|Confirmar identidade, procedimento, local e consentimento com a equipa|Administrar antibiótico após o encerramento', 2, 'A pausa de segurança com confirmação partilhada é um elemento central da cirurgia segura.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas/normas-organizacionais.aspx', 'Demonstração'),
('q-087', 'Cirurgia', 'Feridas', 'Fácil', 'B', 'Gestão do doente', 'Uma ferida superficial recente está visivelmente contaminada. Qual é a primeira medida local?', 'Encerramento imediato sem limpeza|Aplicação de pó antibiótico apenas|Cobrir sem observar|Irrigação abundante e avaliação de tecidos', 3, 'A irrigação e exploração adequada reduzem carga contaminante e permitem decidir desbridamento e encerramento.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-088', 'Cirurgia', 'Abdómen agudo', 'Fácil', 'A', 'Diagnóstico', 'Dor que começa periumbilical e migra para a fossa ilíaca direita, com anorexia e febre baixa, sugere quê?', 'Apendicite aguda|Colecistite aguda|Pancreatite crónica|Obstrução esofágica', 0, 'A migração típica da dor e os sinais focais são sugestivos de apendicite aguda.', 'Conteúdo demonstrativo ACE · WSES', 'https://wjes.biomedcentral.com/', 'Demonstração'),
('q-089', 'Cirurgia', 'Patologia biliar', 'Fácil', 'A', 'Diagnóstico', 'Dor no hipocôndrio direito, febre e sinal de Murphy positivo sugerem que diagnóstico?', 'Apendicite|Colecistite aguda|Diverticulite sigmoide|Pielonefrite esquerda', 1, 'Este padrão clínico é típico de inflamação aguda da vesícula, a confirmar com avaliação laboratorial e ecografia.', 'Conteúdo demonstrativo ACE · WSES', 'https://wjes.biomedcentral.com/', 'Demonstração'),
('q-090', 'Cirurgia', 'Hérnias', 'Fácil', 'B', 'Diagnóstico', 'Uma tumefação inguinal dolorosa deixa de ser redutível e associa-se a vómitos. Qual é a preocupação principal?', 'Lipoma assintomático|Varicocele simples|Encarceramento com possível estrangulamento|Hidrocele comunicante sem urgência', 2, 'Irredutibilidade, dor e obstrução podem indicar compromisso vascular e exigem avaliação cirúrgica urgente.', 'Conteúdo demonstrativo ACE · European Hernia Society', 'https://europeanherniasociety.eu/guidelines/', 'Demonstração'),
('q-091', 'Cirurgia', 'Trauma', 'Fácil', 'A', 'Gestão do doente', 'Na abordagem inicial de trauma major, qual é a prioridade segundo uma sequência estruturada?', 'Obter história familiar completa primeiro|Imobilizar apenas o membro mais doloroso|Realizar ressonância antes da avaliação clínica|Identificar e tratar ameaças imediatas à via aérea e respiração', 3, 'A avaliação primária trata ameaças vitais à medida que são identificadas, começando pela via aérea com proteção cervical.', 'Conteúdo demonstrativo ACE · ERC', 'https://www.erc.edu/science-research/guidelines', 'Demonstração'),
('q-092', 'Cirurgia', 'Queimaduras', 'Fácil', 'A', 'Gestão do doente', 'Qual é o primeiro cuidado local numa queimadura térmica pequena e recente, sem risco de hipotermia?', 'Arrefecer com água corrente fresca durante tempo adequado|Aplicar gelo diretamente|Rebentar todas as bolhas|Aplicar pasta dentífrica', 0, 'O arrefecimento com água corrente limita lesão térmica; gelo pode agravar lesão e hipotermia.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/news-room/fact-sheets/detail/burns', 'Demonstração'),
('q-093', 'Cirurgia', 'Urologia', 'Fácil', 'B', 'Diagnóstico', 'Dor lombar intensa em cólica, irradiada para a virilha, com hematúria, sugere principalmente quê?', 'Aneurisma cerebral|Cólica renal por litíase|Pancreatite|Artrite séptica', 1, 'A cólica ureteral causa dor intensa irradiada e pode associar-se a hematúria.', 'Conteúdo demonstrativo ACE · EAU', 'https://uroweb.org/guidelines', 'Demonstração'),
('q-094', 'Cirurgia', 'Ortopedia', 'Fácil', 'A', 'Gestão do doente', 'Após queda, um membro está deformado, doloroso e sem pulso distal palpável. Qual é a prioridade?', 'Mandar caminhar para testar|Aplicar calor e reavaliar numa semana|Avaliação neurovascular urgente e redução especializada|Ignorar a perfusão se houver sensibilidade', 2, 'Ausência de pulso após trauma sugere compromisso vascular e exige atuação urgente para preservar o membro.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng37', 'Demonstração'),
('q-095', 'Cirurgia', 'Pós-operatório', 'Fácil', 'A', 'Prevenção', 'Qual é uma medida habitual para reduzir tromboembolismo venoso após cirurgia em pessoas elegíveis?', 'Manter repouso absoluto prolongado|Usar antibiótico como profilaxia trombótica|Evitar hidratação em todos os casos|Avaliar risco e usar mobilização e profilaxia adequada', 3, 'A prevenção combina estratificação de risco, mobilização precoce e profilaxia mecânica ou farmacológica quando indicada.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng89', 'Demonstração'),
('q-096', 'Cirurgia', 'Mama', 'Fácil', 'B', 'Diagnóstico', 'Uma pessoa deteta um nódulo mamário novo e persistente. Qual é a atitude apropriada?', 'Avaliação clínica e imagiológica dirigida sem atraso indevido|Assumir benignidade pela ausência de dor|Iniciar antibiótico sempre|Aguardar vários anos', 0, 'Um nódulo novo deve ser avaliado de forma estruturada, combinando clínica, imagem e biópsia quando indicada.', 'Conteúdo demonstrativo ACE · ESMO', 'https://www.esmo.org/guidelines', 'Demonstração'),
('q-097', 'Cirurgia', 'Anestesiologia', 'Fácil', 'A', 'Gestão do doente', 'Antes de anestesia, qual é uma verificação essencial?', 'Omitir medicação habitual da história|Avaliar via aérea, alergias, jejum e risco anestésico|Dispensar identificação do doente|Ignorar próteses dentárias', 1, 'A avaliação pré-anestésica identifica riscos modificáveis e prepara uma estratégia segura.', 'Conteúdo demonstrativo ACE · ESAIC', 'https://esaic.org/guidelines/', 'Demonstração'),
('q-098', 'Cirurgia', 'Estomas', 'Fácil', 'B', 'Gestão do doente', 'Um estoma saudável no pós-operatório imediato deve apresentar habitualmente que aspeto?', 'Negro e seco|Branco e insensível|Rosado ou vermelho e húmido|Azul-escuro persistente', 2, 'Um estoma viável é húmido e bem perfundido; escurecimento ou palidez persistente requer avaliação urgente.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas-dqs/normas-clinicas.aspx', 'Demonstração'),
('q-099', 'Cirurgia', 'Abdómen agudo', 'Média', 'A', 'Diagnóstico', 'Dor no quadrante inferior esquerdo, febre e alteração do trânsito numa pessoa mais velha sugerem sobretudo quê?', 'Apendicite retrocecal|Colecistite|Úlcera duodenal perfurada|Diverticulite aguda', 3, 'O quadro é compatível com diverticulite aguda; a gravidade e complicações orientam a necessidade de imagem.', 'Conteúdo demonstrativo ACE · WSES', 'https://wjes.biomedcentral.com/', 'Demonstração'),
('q-100', 'Cirurgia', 'Obstrução intestinal', 'Média', 'A', 'Diagnóstico', 'Dor abdominal em cólica, vómitos, distensão e ausência de dejeções sugerem que síndrome?', 'Obstrução intestinal mecânica|Hepatite isolada|Pneumonia lobar|Cistite simples', 0, 'A combinação de cólica, vómitos, distensão e obstipação é típica de obstrução intestinal.', 'Conteúdo demonstrativo ACE · WSES', 'https://wjes.biomedcentral.com/', 'Demonstração'),
('q-101', 'Cirurgia', 'Patologia biliar', 'Média', 'A', 'Gestão do doente', 'Uma pessoa com febre, icterícia e dor no hipocôndrio direito tem suspeita de colangite. Qual é a abordagem?', 'Alta com dieta pobre em gordura|Antibiótico, suporte e avaliação urgente para drenagem biliar|Colonoscopia eletiva|Apenas analgesia tópica', 1, 'A colangite é uma infeção com obstrução biliar; requer estabilização, antimicrobianos e controlo da obstrução.', 'Conteúdo demonstrativo ACE · Tokyo Guidelines', 'https://www.jshbps.jp/modules/en/index.php?content_id=47', 'Demonstração'),
('q-102', 'Cirurgia', 'Trauma torácico', 'Média', 'A', 'Gestão do doente', 'Após trauma, há dispneia grave, hipotensão, ausência unilateral de murmúrio e desvio traqueal. Qual é a ação?', 'Aguardar radiografia antes de intervir|Fazer espirometria|Descompressão imediata de pneumotórax hipertensivo|Administrar diurético isolado', 2, 'O pneumotórax hipertensivo é um diagnóstico clínico em instabilidade e deve ser descomprimido sem atraso para imagem.', 'Conteúdo demonstrativo ACE · ERC', 'https://www.erc.edu/science-research/guidelines', 'Demonstração'),
('q-103', 'Cirurgia', 'Trauma craniano', 'Média', 'A', 'Diagnóstico', 'Que mudança num traumatismo craniano exige reavaliação neurológica urgente?', 'Dor ligeira estável no couro cabeludo|Fome após observação|Equimose antiga no joelho|Queda da pontuação de Glasgow', 3, 'Deterioração do estado de consciência pode indicar lesão intracraniana em progressão e exige resposta imediata.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng232', 'Demonstração'),
('q-104', 'Cirurgia', 'Cirurgia vascular', 'Média', 'A', 'Diagnóstico', 'Dor súbita num membro, palidez, ausência de pulso, parestesias e fraqueza indicam quê?', 'Isquemia aguda do membro|Insuficiência venosa crónica simples|Celulite ligeira|Neuropatia estável', 0, 'Os sinais clássicos de isquemia aguda indicam ameaça ao membro e necessidade de avaliação vascular urgente.', 'Conteúdo demonstrativo ACE · ESVS', 'https://esvs.org/guidelines/', 'Demonstração'),
('q-105', 'Cirurgia', 'Urologia', 'Média', 'A', 'Gestão do doente', 'Uma pessoa com cólica renal apresenta febre, hipotensão e hidronefrose. Qual é a prioridade?', 'Litotrícia eletiva meses depois sem tratar infeção|Antibiótico e descompressão urgente do trato urinário|Apenas anti-inflamatório|Aumentar ingestão e dar alta', 1, 'Obstrução urinária infetada é uma emergência que exige controlo séptico e drenagem.', 'Conteúdo demonstrativo ACE · EAU', 'https://uroweb.org/guidelines', 'Demonstração'),
('q-106', 'Cirurgia', 'Ortopedia', 'Média', 'B', 'Diagnóstico', 'Dor intensa desproporcionada, dor à mobilização passiva e tensão de um compartimento após fratura sugerem quê?', 'Entorse ligeira|Bursite crónica|Síndrome compartimental aguda|Osteoporose', 2, 'A síndrome compartimental é uma emergência; o diagnóstico é sobretudo clínico e o atraso ameaça músculo e nervo.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng37', 'Demonstração'),
('q-107', 'Cirurgia', 'Pós-operatório', 'Média', 'A', 'Diagnóstico', 'No quinto dia após cirurgia, uma ferida torna-se dolorosa, eritematosa e drena pus. Qual é a hipótese?', 'Cicatrização normal obrigatória|Alergia alimentar|Trombose arterial distante|Infeção do local cirúrgico', 3, 'Dor crescente, eritema e drenagem purulenta são sinais de infeção e exigem avaliação da profundidade e controlo do foco.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas-dqs/normas-clinicas.aspx', 'Demonstração'),
('q-108', 'Cirurgia', 'Nutrição perioperatória', 'Média', 'B', 'Gestão do doente', 'Uma pessoa desnutrida necessita de cirurgia major não emergente. Que princípio é adequado?', 'Avaliar risco nutricional e otimizar suporte quando possível|Ignorar perda ponderal|Prescrever jejum por vários dias|Usar nutrição parentérica em todos sem avaliação', 0, 'A identificação e otimização nutricional reduzem complicações, escolhendo a via entérica sempre que apropriada.', 'Conteúdo demonstrativo ACE · ESPEN', 'https://www.espen.org/guidelines-home/espen-guidelines', 'Demonstração'),
('q-109', 'Cirurgia', 'Proctologia', 'Média', 'B', 'Diagnóstico', 'Dor anal intensa durante e após a defecação, com pequena hemorragia viva, é típica de quê?', 'Hemorragia digestiva alta|Fissura anal|Fístula aortoentérica|Cancro pancreático', 1, 'A fissura anal costuma causar dor cortante associada à defecação e sangue vermelho vivo em pequena quantidade.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-110', 'Cirurgia', 'Mama', 'Média', 'B', 'Diagnóstico', 'Uma mulher a amamentar apresenta área mamária eritematosa, dolorosa e febre. Qual é a hipótese mais provável?', 'Carcinoma inflamatório confirmado|Fibroadenoma|Mastite lactacional|Ectasia ductal assintomática', 2, 'Mastite lactacional causa dor focal, eritema e sintomas sistémicos; deve avaliar-se abcesso se não houver resposta.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/health-topics/breastfeeding', 'Demonstração'),
('q-111', 'Cirurgia', 'Anestesiologia', 'Média', 'A', 'Gestão do doente', 'Durante anestesia, surgem aumento rápido de dióxido de carbono expirado, rigidez e hipertermia. Qual é a suspeita?', 'Hipotiroidismo|Hipoglicemia ligeira|Reação vasovagal|Hipertermia maligna', 3, 'A hipertermia maligna exige suspensão dos agentes desencadeantes, dantroleno e suporte intensivo.', 'Conteúdo demonstrativo ACE · ESAIC', 'https://esaic.org/guidelines/', 'Demonstração'),
('q-112', 'Cirurgia', 'Abdómen agudo', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa com dor abdominal súbita apresenta ar livre subdiafragmático e sinais de peritonite. Qual é a conduta?', 'Ressuscitação, antibiótico e avaliação cirúrgica urgente para perfuração|Colonoscopia imediata sem preparação|Alta com inibidor da bomba de protões|Observação domiciliária', 0, 'Perfuração de víscera oca com peritonite requer estabilização, antimicrobianos e controlo cirúrgico do foco.', 'Conteúdo demonstrativo ACE · WSES', 'https://wjes.biomedcentral.com/', 'Demonstração'),
('q-113', 'Cirurgia', 'Isquemia mesentérica', 'Difícil', 'A', 'Diagnóstico', 'Uma pessoa com fibrilhação auricular tem dor abdominal intensa desproporcionada, lactato crescente e poucos achados iniciais. Qual é o exame prioritário?', 'Trânsito baritado|Angio-TC mesentérica urgente|Colonoscopia de rastreio|Ecografia tiroideia', 1, 'A angio-TC permite avaliar rapidamente vasos e intestino quando se suspeita de isquemia mesentérica aguda.', 'Conteúdo demonstrativo ACE · ESVS', 'https://esvs.org/guidelines/', 'Demonstração'),
('q-114', 'Cirurgia', 'Hemorragia', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa com hemorragia maciça continua instável apesar de medidas iniciais. Que princípio de ressuscitação é adequado?', 'Administrar apenas cristaloide em volume ilimitado|Adiar hemostase até normalizar todos os exames|Ativar protocolo de hemorragia maciça e controlar rapidamente a fonte|Evitar aquecimento ativo', 2, 'A abordagem coordena hemoderivados, correção de hipotermia e coagulopatia e controlo precoce da hemorragia.', 'Conteúdo demonstrativo ACE · ESAIC', 'https://esaic.org/guidelines/', 'Demonstração'),
('q-115', 'Cirurgia', 'Trauma pélvico', 'Difícil', 'A', 'Gestão do doente', 'Um traumatizado instável apresenta suspeita de fratura pélvica e hemorragia. Qual é uma medida inicial útil?', 'Mobilizar repetidamente a bacia|Aguardar ressonância|Fazer marcha assistida|Aplicar estabilizador pélvico na posição correta e ativar controlo hemorrágico', 3, 'A estabilização pélvica reduz volume e movimento, integrando uma estratégia urgente de controlo da hemorragia.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng37', 'Demonstração'),
('q-116', 'Cirurgia', 'Cirurgia vascular', 'Difícil', 'A', 'Diagnóstico', 'Uma pessoa com aneurisma da aorta conhecido apresenta dor abdominal súbita, hipotensão e massa pulsátil. Qual é a hipótese?', 'Rotura de aneurisma da aorta abdominal|Colecistite simples|Cólica renal não complicada|Hérnia umbilical redutível', 0, 'A tríade clássica, embora nem sempre completa, deve desencadear via urgente para possível rotura de aneurisma.', 'Conteúdo demonstrativo ACE · ESVS', 'https://esvs.org/guidelines/', 'Demonstração'),
('q-117', 'Cirurgia', 'Urologia', 'Difícil', 'A', 'Gestão do doente', 'Dor testicular súbita, testículo elevado e reflexo cremastérico ausente num adolescente sugerem quê?', 'Epididimite crónica sem urgência|Torção testicular com exploração urgente|Hidrocele simples|Varicocele assintomática', 1, 'A torção ameaça a viabilidade testicular; forte suspeita clínica não deve aguardar exames que atrasem cirurgia.', 'Conteúdo demonstrativo ACE · EAU', 'https://uroweb.org/guidelines', 'Demonstração'),
('q-118', 'Cirurgia', 'Ortopedia', 'Difícil', 'A', 'Diagnóstico', 'Uma pessoa com prótese articular apresenta febre, dor aguda e derrame. Que diagnóstico deve ser excluído rapidamente?', 'Osteoartrose fisiológica|Fibromialgia|Infeção periprotética|Tendinopatia simples', 2, 'A infeção periprotética exige colheitas adequadas e estratégia multidisciplinar; antibiótico prévio pode reduzir rendimento cultural.', 'Conteúdo demonstrativo ACE · EBJIS', 'https://ebjis.org/', 'Demonstração'),
('q-119', 'Cirurgia', 'Pós-operatório', 'Difícil', 'A', 'Diagnóstico', 'Após cirurgia abdominal, surgem taquicardia persistente, dor crescente, febre e conteúdo entérico no dreno. Qual é a preocupação?', 'Íleo fisiológico simples|Infeção urinária assintomática|Reação ao adesivo|Deiscência de anastomose', 3, 'O conjunto sugere fuga anastomótica e sépsis, requerendo imagem e controlo urgente do foco.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-120', 'Cirurgia', 'Queimaduras', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa com queimadura facial em espaço fechado apresenta fuligem oral e rouquidão progressiva. Qual é a prioridade?', 'Proteger precocemente a via aérea|Aguardar edema máximo antes de agir|Aplicar apenas creme tópico|Dar líquidos por via oral', 0, 'Sinais de lesão inalatória podem preceder edema grave; a via aérea deve ser assegurada por equipa experiente.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/news-room/fact-sheets/detail/burns', 'Demonstração'),
('q-121', 'Cirurgia', 'Endocrinologia cirúrgica', 'Difícil', 'B', 'Gestão do doente', 'Após tiroidectomia, uma pessoa desenvolve estridor e tumefação cervical rápida. Qual é a prioridade?', 'Pedir análise da tiroglobulina|Reconhecer hematoma compressivo e libertar urgentemente a via aérea|Administrar ferro oral|Marcar ecografia em seis meses', 1, 'Um hematoma cervical expansivo pode obstruir a via aérea e necessita de descompressão e controlo imediato.', 'Conteúdo demonstrativo ACE · BAETS', 'https://baets.org.uk/guidelines/', 'Demonstração'),
('q-122', 'Cirurgia', 'Transplantação', 'Difícil', 'C', 'Diagnóstico', 'Dias após transplante renal, há oligúria e aumento da creatinina. Que princípio diagnóstico é correto?', 'Assumir sempre rejeição sem exames|Suspender imunossupressão automaticamente|Avaliar causas pré-renais, obstrução, toxicidade e rejeição de forma urgente|Esperar um mês', 2, 'A disfunção precoce do enxerto tem múltiplas causas e requer avaliação estruturada, incluindo perfusão e ecografia.', 'Conteúdo demonstrativo ACE · KDIGO', 'https://kdigo.org/guidelines/', 'Demonstração'),
('q-123', 'Cirurgia', 'Cirurgia oncológica', 'Difícil', 'B', 'Gestão do doente', 'Antes de operar um tumor sólido potencialmente ressecável, qual é um princípio essencial?', 'Operar sem imagem nem histologia sempre|Ignorar estado funcional|Excluir preferências do doente|Confirmar diagnóstico, estadiamento e discussão multidisciplinar', 3, 'A decisão oncológica integra diagnóstico, extensão, ressecabilidade, condição da pessoa e alternativas terapêuticas.', 'Conteúdo demonstrativo ACE · ESMO', 'https://www.esmo.org/guidelines', 'Demonstração');
insert into questions (id, area, topic, difficulty, relevance, competency, stem, options_text, correct_index, explanation, source_name, source_url, status) values
('q-124', 'Ginecologia/Obstetrícia', 'Preconceção', 'Fácil', 'A', 'Prevenção', 'Que suplemento é recomendado antes da conceção e no início da gravidez para reduzir defeitos do tubo neural?', 'Ácido fólico em dose adequada ao risco|Vitamina A em alta dose|Ferro endovenoso universal|Cálcio apenas após o parto', 0, 'A suplementação periconcecional com ácido fólico reduz o risco de defeitos do tubo neural.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-orientacoes-e-informacoes/normas-e-circulares-normativas.aspx', 'Demonstração'),
('q-125', 'Ginecologia/Obstetrícia', 'Gravidez ectópica', 'Fácil', 'A', 'Diagnóstico', 'Uma mulher com atraso menstrual apresenta dor pélvica unilateral e hemorragia vaginal. Que diagnóstico deve ser excluído?', 'Vaginose bacteriana isolada|Gravidez ectópica|Menopausa|Prolapso uterino', 1, 'Dor e hemorragia no início de uma possível gravidez exigem avaliação para localização e viabilidade, incluindo exclusão de ectópica.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng126', 'Demonstração'),
('q-126', 'Ginecologia/Obstetrícia', 'Trabalho de parto', 'Fácil', 'A', 'Diagnóstico', 'Contrações regulares dolorosas associadas a modificação progressiva do colo indicam quê?', 'Braxton Hicks sem alteração cervical|Infeção urinária simples|Trabalho de parto|Descolamento prematuro obrigatório', 2, 'O diagnóstico de trabalho de parto assenta em contrações regulares com apagamento e dilatação cervical progressivos.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241550215', 'Demonstração'),
('q-127', 'Ginecologia/Obstetrícia', 'Puerpério', 'Fácil', 'A', 'Gestão do doente', 'Hemorragia vaginal abundante e útero amolecido logo após o parto sugerem sobretudo quê?', 'Endometriose|Gravidez ectópica|Vaginismo|Atonia uterina', 3, 'A atonia é uma causa frequente de hemorragia pós-parto e requer massagem uterina, uterotónicos e escalada conforme resposta.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-128', 'Ginecologia/Obstetrícia', 'Contraceção', 'Fácil', 'A', 'Gestão do doente', 'Numa mulher com enxaqueca com aura, que componente contracetivo exige particular cautela pelo risco vascular?', 'Estrogénio|Cobre intrauterino|Barreira física|Progestagénio isolado em todos os contextos', 0, 'Contraceção combinada com estrogénio pode ser contraindicada na enxaqueca com aura; deve escolher-se método seguro individualizado.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241549158', 'Demonstração'),
('q-129', 'Ginecologia/Obstetrícia', 'Infeções sexualmente transmissíveis', 'Fácil', 'A', 'Prevenção', 'Qual é uma medida que reduz simultaneamente risco de várias infeções sexualmente transmissíveis?', 'Antibiótico após todas as relações|Uso correto e consistente de preservativo|Contraceção hormonal isolada|Lavagem vaginal', 1, 'O preservativo reduz transmissão de várias IST quando usado correta e consistentemente, embora não elimine todo o risco.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/pns-e-programas/programas-de-saude-prioritarios/infecoes-sexualmente-transmissiveis-e-infecao-vih.aspx', 'Demonstração'),
('q-130', 'Ginecologia/Obstetrícia', 'Rastreio cervical', 'Fácil', 'A', 'Prevenção', 'Qual é o princípio correto do rastreio do cancro do colo do útero?', 'Usar sintomas como único critério|Fazer citologia mensal|Seguir o programa populacional aplicável mesmo na ausência de sintomas|Parar sempre após a primeira colheita normal', 2, 'O rastreio deve seguir intervalos e testes do programa aplicável; sintomas exigem avaliação fora do rastreio.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/pns-e-programas/programas-de-saude-prioritarios/doencas-oncologicas.aspx', 'Demonstração'),
('q-131', 'Ginecologia/Obstetrícia', 'Menopausa', 'Fácil', 'B', 'Diagnóstico', 'A menopausa natural é habitualmente definida após quanto tempo de amenorreia sem outra causa?', 'Duas semanas|Três meses|Cinco anos|Doze meses', 3, 'Em idade apropriada, doze meses consecutivos sem menstruação e sem outra causa definem menopausa natural.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng23', 'Demonstração'),
('q-132', 'Ginecologia/Obstetrícia', 'Endometriose', 'Fácil', 'B', 'Diagnóstico', 'Dismenorreia progressiva, dor pélvica cíclica e dispareunia profunda sugerem que diagnóstico?', 'Endometriose|Cistite aguda|Vulvovaginite candidiásica|Gravidez molar', 0, 'Dor pélvica cíclica e dispareunia podem indicar endometriose, que deve ser avaliada sem normalizar sofrimento incapacitante.', 'Conteúdo demonstrativo ACE · ESHRE', 'https://www.eshre.eu/Guidelines-and-Legal/Guidelines/Endometriosis-guideline', 'Demonstração'),
('q-133', 'Ginecologia/Obstetrícia', 'Síndrome do ovário poliquístico', 'Fácil', 'B', 'Diagnóstico', 'Ciclos irregulares, hirsutismo e sinais de resistência à insulina sugerem que síndrome?', 'Insuficiência ovárica prematura obrigatória|Síndrome do ovário poliquístico|Endometrite|Prolapso genital', 1, 'A disfunção ovulatória e hiperandrogenismo, após exclusão de outras causas, são centrais no diagnóstico de SOP.', 'Conteúdo demonstrativo ACE · ESHRE', 'https://www.eshre.eu/Guidelines-and-Legal/Guidelines', 'Demonstração'),
('q-134', 'Ginecologia/Obstetrícia', 'Prolapso genital', 'Fácil', 'C', 'Diagnóstico', 'Sensação de peso pélvico e massa vaginal que piora ao fim do dia sugerem quê?', 'Doença inflamatória pélvica aguda|Gravidez ectópica|Prolapso de órgãos pélvicos|Amenorreia hipotalâmica', 2, 'A sensação de abaulamento vaginal é o sintoma mais específico de prolapso de órgãos pélvicos.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng123', 'Demonstração'),
('q-135', 'Ginecologia/Obstetrícia', 'Vigilância da gravidez', 'Fácil', 'A', 'Prevenção', 'Qual é um objetivo central das consultas pré-natais?', 'Garantir cesariana a todas as grávidas|Evitar discussão de saúde mental|Substituir todas as ecografias por radiografias|Identificar riscos maternos e fetais e promover cuidados preventivos', 3, 'A vigilância pré-natal combina avaliação clínica, rastreios, prevenção, informação e planeamento individualizado.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-orientacoes-e-informacoes/normas-e-circulares-normativas.aspx', 'Demonstração'),
('q-136', 'Ginecologia/Obstetrícia', 'Aleitamento', 'Fácil', 'B', 'Gestão do doente', 'Qual é uma intervenção útil perante dor ao amamentar nos primeiros dias?', 'Observar pega e posição e oferecer apoio individualizado|Suspender definitivamente sem avaliar|Limitar todas as mamadas a dois minutos|Prescrever antibiótico universal', 0, 'A observação de uma mamada permite corrigir pega e posicionamento e identificar outras causas de dor.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/health-topics/breastfeeding', 'Demonstração'),
('q-137', 'Ginecologia/Obstetrícia', 'Diabetes gestacional', 'Média', 'A', 'Gestão do doente', 'Após diagnóstico de diabetes gestacional, qual é um componente inicial habitual do tratamento?', 'Jejum prolongado|Plano alimentar, atividade segura e automonitorização glicémica|Insulina sem qualquer educação|Suspensão de toda a ingestão de hidratos de carbono', 1, 'Mudanças de estilo de vida e monitorização são iniciais, acrescentando fármaco quando as metas não são atingidas.', 'Conteúdo demonstrativo ACE · DGS', 'https://www.dgs.pt/normas-clinicas-dqs/normas-clinicas.aspx', 'Demonstração'),
('q-138', 'Ginecologia/Obstetrícia', 'Rotura prematura de membranas', 'Média', 'A', 'Diagnóstico', 'Uma grávida refere saída súbita e contínua de líquido claro por via vaginal antes do trabalho de parto. Qual é a suspeita?', 'Incontinência fecal|Descolamento da placenta obrigatório|Rotura de membranas|Cólica renal', 2, 'A história sugere rotura de membranas, a confirmar com exame apropriado evitando toque vaginal digital desnecessário.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng25', 'Demonstração'),
('q-139', 'Ginecologia/Obstetrícia', 'Bem-estar fetal', 'Média', 'A', 'Gestão do doente', 'Uma grávida refere diminuição marcada dos movimentos fetais. Qual é a orientação apropriada?', 'Esperar uma semana|Tomar sedativo e dormir|Iniciar exercício vigoroso|Avaliação obstétrica no próprio dia', 3, 'A redução de movimentos pode ser sinal de compromisso fetal e requer avaliação atempada conforme idade gestacional.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-140', 'Ginecologia/Obstetrícia', 'Placenta prévia', 'Média', 'A', 'Diagnóstico', 'Hemorragia vaginal vermelho vivo, indolor, no terceiro trimestre sugere principalmente quê?', 'Placenta prévia|Descolamento prematuro da placenta|Rotura uterina|Pielonefrite', 0, 'A hemorragia indolor tardia é uma apresentação típica de placenta prévia; deve evitar-se toque digital até conhecer a localização.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-141', 'Ginecologia/Obstetrícia', 'Descolamento prematuro da placenta', 'Média', 'A', 'Diagnóstico', 'Hemorragia vaginal dolorosa, útero hipertónico e sofrimento fetal sugerem quê?', 'Placenta prévia assintomática|Descolamento prematuro da placenta|Vaginose bacteriana|Incompetência cervical', 1, 'Dor, hipertonia e alterações fetais são sugestivas de descolamento, que pode existir mesmo com pouca hemorragia externa.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-142', 'Ginecologia/Obstetrícia', 'Distocia', 'Média', 'B', 'Diagnóstico', 'Durante o trabalho de parto, a dilatação deixa de progredir. Qual é um princípio antes de intervir?', 'Realizar cesariana sem qualquer avaliação|Administrar ocitocina apesar de contraindicação|Reavaliar potência das contrações, passageiro e canal de parto|Ignorar estado fetal', 2, 'A falta de progressão exige avaliação sistemática da dinâmica, posição, proporção e bem-estar materno-fetal.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241550215', 'Demonstração'),
('q-143', 'Ginecologia/Obstetrícia', 'Distocia de ombros', 'Média', 'A', 'Gestão do doente', 'Após saída da cabeça fetal, os ombros não progridem e ocorre retração da cabeça. Qual é a resposta?', 'Aplicar pressão fúndica vigorosa|Tração cervical contínua|Aguardar sem comunicar|Pedir ajuda e iniciar manobras protocoladas para distocia de ombros', 3, 'A distocia de ombros é uma emergência; comunicação, McRoberts e pressão suprapúbica integram a resposta inicial.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-144', 'Ginecologia/Obstetrícia', 'Infeção puerperal', 'Média', 'A', 'Diagnóstico', 'Febre, dor uterina e lóquios fétidos após o parto sugerem que diagnóstico?', 'Endometrite puerperal|Mastalgia fisiológica|Trombose arterial do braço|Endometriose', 0, 'A endometrite pós-parto apresenta febre e hipersensibilidade uterina, exigindo avaliação séptica e antibiótico adequado.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-145', 'Ginecologia/Obstetrícia', 'Urgência ginecológica', 'Média', 'A', 'Diagnóstico', 'Dor pélvica unilateral súbita, vómitos e massa anexial sugerem que urgência?', 'Cervicite simples|Torção anexial|Amenorreia fisiológica|Prolapso assintomático', 1, 'A torção compromete o fluxo ovárico; forte suspeita justifica avaliação ginecológica urgente.', 'Conteúdo demonstrativo ACE · ACOG', 'https://www.acog.org/clinical', 'Demonstração'),
('q-146', 'Ginecologia/Obstetrícia', 'Doença inflamatória pélvica', 'Média', 'A', 'Gestão do doente', 'Dor pélvica, corrimento e dor à mobilização cervical levantam suspeita de DIP. Qual é um princípio terapêutico?', 'Aguardar sempre por cultura positiva|Tratar apenas o parceiro|Iniciar antibioterapia empírica quando a suspeita clínica é suficiente|Prescrever antifúngico isolado', 2, 'O atraso aumenta sequelas; o tratamento empírico cobre agentes prováveis e inclui abordagem de parceiros e prevenção.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-147', 'Ginecologia/Obstetrícia', 'Hemorragia uterina anormal', 'Média', 'B', 'Diagnóstico', 'Numa mulher em idade reprodutiva com hemorragia uterina anormal, qual é um teste inicial que não deve ser omitido?', 'Marcador tumoral CA 19-9|Amniocentese|Densitometria óssea|Teste de gravidez', 3, 'A gravidez e suas complicações devem ser excluídas cedo na avaliação de hemorragia uterina anormal.', 'Conteúdo demonstrativo ACE · FIGO', 'https://www.figo.org/resources/figo-statements', 'Demonstração'),
('q-148', 'Ginecologia/Obstetrícia', 'Contraceção', 'Média', 'B', 'Gestão do doente', 'Qual é o princípio de uma consulta de escolha contracetiva?', 'Decisão partilhada com eficácia, riscos, preferências e reversibilidade|Impor o método com maior eficácia|Omitir efeitos adversos|Excluir métodos de longa duração da discussão', 0, 'A escolha deve ser informada, voluntária e adequada às condições clínicas e prioridades da pessoa.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241549158', 'Demonstração'),
('q-149', 'Ginecologia/Obstetrícia', 'Pré-eclâmpsia', 'Média', 'A', 'Diagnóstico', 'Após 20 semanas, hipertensão nova com proteinúria ou disfunção de órgão materno sugere quê?', 'Hipotensão fisiológica|Pré-eclâmpsia|Diabetes insípida|Gravidez molar confirmada', 1, 'A pré-eclâmpsia é definida por hipertensão de novo associada a proteinúria e ou disfunção materna ou placentária.', 'Conteúdo demonstrativo ACE · ISSHP', 'https://isshp.org/guidelines/', 'Demonstração'),
('q-150', 'Ginecologia/Obstetrícia', 'Eclâmpsia', 'Difícil', 'A', 'Gestão do doente', 'Uma grávida hipertensa apresenta convulsão tónico-clónica sem outra causa evidente. Qual é o anticonvulsivante de escolha?', 'Fenitoína oral como primeira opção universal|Haloperidol|Sulfato de magnésio|Carbamazepina de manutenção antes de estabilizar', 2, 'O sulfato de magnésio trata e previne recorrência de convulsões eclâmpticas, em paralelo com estabilização materna e planeamento do parto.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-151', 'Ginecologia/Obstetrícia', 'Síndrome HELLP', 'Difícil', 'A', 'Diagnóstico', 'Uma grávida com pré-eclâmpsia apresenta dor epigástrica, hemólise, enzimas hepáticas elevadas e plaquetas baixas. Qual é o diagnóstico?', 'Colestase gravídica isolada|Hiperémese simples|Diabetes gestacional|Síndrome HELLP', 3, 'Hemólise, elevação de enzimas hepáticas e trombocitopenia definem HELLP, uma emergência obstétrica.', 'Conteúdo demonstrativo ACE · ISSHP', 'https://isshp.org/guidelines/', 'Demonstração'),
('q-152', 'Ginecologia/Obstetrícia', 'Gravidez ectópica', 'Difícil', 'A', 'Gestão do doente', 'Uma mulher com teste de gravidez positivo apresenta dor intensa, síncope, hipotensão e líquido livre abdominal. Qual é a prioridade?', 'Ressuscitação e tratamento cirúrgico urgente de provável ectópica rota|Repetir teste em duas semanas|Iniciar contraceção oral|Dar alta com analgesia', 0, 'Instabilidade e hemoperitoneu em possível gravidez ectópica indicam rotura até prova em contrário.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng126', 'Demonstração'),
('q-153', 'Ginecologia/Obstetrícia', 'Embolia de líquido amniótico', 'Difícil', 'C', 'Diagnóstico', 'Durante o parto, uma mulher desenvolve subitamente hipoxemia, hipotensão e coagulopatia grave. Que diagnóstico raro deve ser considerado?', 'Hiperémese gravídica|Embolia de líquido amniótico|Endometriose|Síndrome do ovário poliquístico', 1, 'Colapso cardiorrespiratório abrupto e coagulação intravascular disseminada periparto são compatíveis com este diagnóstico de exclusão.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-154', 'Ginecologia/Obstetrícia', 'Rotura uterina', 'Difícil', 'A', 'Diagnóstico', 'Em trabalho de parto após cesariana prévia, surgem dor súbita, bradicardia fetal e perda da apresentação. Qual é a preocupação?', 'Placenta prévia estável|Cistite|Rotura uterina|Vaginose', 2, 'Alteração fetal súbita e perda da estação, sobretudo com cicatriz uterina, sugerem rotura e exigem laparotomia urgente.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-155', 'Ginecologia/Obstetrícia', 'Prolapso do cordão', 'Difícil', 'A', 'Gestão do doente', 'Após rotura de membranas, há bradicardia fetal e o cordão é palpável antes da apresentação. Qual é a ação?', 'Empurrar o cordão repetidamente para o útero|Aguardar recuperação durante horas|Estimular contrações com ocitocina|Elevar a apresentação, pedir ajuda e preparar parto urgente', 3, 'É necessário aliviar compressão do cordão e acelerar o parto por via apropriada.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-156', 'Ginecologia/Obstetrícia', 'Vasa prévia', 'Difícil', 'B', 'Diagnóstico', 'Logo após rotura de membranas ocorre hemorragia vaginal indolor e bradicardia fetal profunda. Que diagnóstico deve ser lembrado?', 'Rotura de vasa prévia|Atonia uterina|Gravidez ectópica|Endometrite puerperal', 0, 'A rotura de vasos fetais desprotegidos causa hemorragia fetal rápida e compromisso agudo.', 'Conteúdo demonstrativo ACE · RCOG', 'https://www.rcog.org.uk/guidance/', 'Demonstração'),
('q-157', 'Ginecologia/Obstetrícia', 'Hemorragia pós-parto', 'Difícil', 'A', 'Gestão do doente', 'Uma hemorragia pós-parto persiste apesar de massagem e uterotónico inicial. Qual é o princípio seguinte?', 'Continuar indefinidamente a mesma medida|Escalar protocolo, procurar os quatro T e controlar a fonte|Transferir sem ressuscitação|Esperar pela hemoglobina do dia seguinte', 1, 'A equipa deve ressuscitar e procurar tónus, trauma, tecido e trombina, escalando fármacos, dispositivos e cirurgia.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-158', 'Ginecologia/Obstetrícia', 'Sépsis obstétrica', 'Difícil', 'A', 'Gestão do doente', 'Após aborto, uma mulher apresenta febre, choque, dor pélvica e corrimento fétido. Qual é a abordagem?', 'Esperar cultura sem tratar|Prescrever apenas analgésico|Ressuscitação, antibiótico de largo espetro e controlo urgente do foco|Iniciar estrogénio', 2, 'Sépsis obstétrica requer tratamento imediato e remoção de tecido infetado quando presente.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/who-guidelines', 'Demonstração'),
('q-159', 'Ginecologia/Obstetrícia', 'Reprodução medicamente assistida', 'Difícil', 'C', 'Diagnóstico', 'Após estimulação ovárica, uma mulher apresenta ascite, ovários aumentados, hemoconcentração e dispneia. Qual é a síndrome?', 'Síndrome de Asherman|Menopausa|Vaginismo|Síndrome de hiperestimulação ovárica', 3, 'O aumento da permeabilidade vascular após estimulação pode causar hiperestimulação ovárica e trombose ou falência orgânica.', 'Conteúdo demonstrativo ACE · ESHRE', 'https://www.eshre.eu/Guidelines-and-Legal/Guidelines', 'Demonstração'),
('q-160', 'Ginecologia/Obstetrícia', 'Oncologia ginecológica', 'Difícil', 'B', 'Diagnóstico', 'Uma mulher pós-menopáusica apresenta hemorragia vaginal. Qual é a prioridade diagnóstica?', 'Excluir patologia endometrial maligna|Assumir atrofia sem avaliar|Prescrever contraceção combinada|Realizar apenas urocultura', 0, 'Hemorragia pós-menopausa exige investigação rápida do endométrio, mesmo que causas benignas sejam frequentes.', 'Conteúdo demonstrativo ACE · ESGO', 'https://www.esgo.org/explore/guidelines/', 'Demonstração'),
('q-161', 'Ginecologia/Obstetrícia', 'Monitorização fetal', 'Difícil', 'A', 'Gestão do doente', 'Durante o parto, um traçado apresenta bradicardia prolongada e variabilidade ausente. Qual é a resposta?', 'Continuar ocitocina sem alteração|Medidas intrauterinas imediatas, suspensão de causas reversíveis e preparação para parto urgente|Ignorar por trinta minutos|Administrar sedativo materno', 1, 'Um padrão gravemente patológico exige correção de causas reversíveis e nascimento expedito se não recuperar.', 'Conteúdo demonstrativo ACE · FIGO', 'https://www.figo.org/resources/figo-statements', 'Demonstração'),
('q-162', 'Ginecologia/Obstetrícia', 'Cardiologia obstétrica', 'Difícil', 'B', 'Diagnóstico', 'No último mês da gravidez, uma mulher apresenta dispneia progressiva, ortopneia e disfunção sistólica sem causa prévia. Que diagnóstico considerar?', 'Asma ligeira|Refluxo fisiológico|Cardiomiopatia periparto|Ataque de pânico isolado', 2, 'Insuficiência cardíaca com disfunção ventricular no final da gestação ou puerpério pode corresponder a cardiomiopatia periparto.', 'Conteúdo demonstrativo ACE · ESC', 'https://www.escardio.org/Guidelines', 'Demonstração');
insert into questions (id, area, topic, difficulty, relevance, competency, stem, options_text, correct_index, explanation, source_name, source_url, status) values
('q-163', 'Psiquiatria', 'Perturbações do humor', 'Fácil', 'A', 'Diagnóstico', 'Humor deprimido, anedonia, fadiga e alteração do sono durante várias semanas sugerem principalmente quê?', 'Delirium hiperativo|Perturbação de pânico isolada|Intoxicação aguda obrigatória|Episódio depressivo', 3, 'A combinação persistente de humor deprimido ou anedonia com sintomas associados é compatível com episódio depressivo.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241549790', 'Demonstração'),
('q-164', 'Psiquiatria', 'Ansiedade', 'Fácil', 'B', 'Diagnóstico', 'Preocupação excessiva em várias áreas da vida, difícil de controlar e acompanhada de tensão por meses, sugere quê?', 'Perturbação de ansiedade generalizada|Esquizofrenia|Delirium|Perturbação bipolar em mania', 0, 'A preocupação persistente e generalizada com sintomas de tensão é característica de ansiedade generalizada.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg113', 'Demonstração'),
('q-165', 'Psiquiatria', 'Ansiedade', 'Fácil', 'A', 'Diagnóstico', 'Episódios inesperados de medo intenso, palpitações e sensação de morte iminente, com receio de recorrência, sugerem quê?', 'Fobia específica sem ataques|Perturbação de pânico|Demência|Catatonia', 1, 'Ataques inesperados recorrentes seguidos de preocupação persistente são compatíveis com perturbação de pânico.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg113', 'Demonstração'),
('q-166', 'Psiquiatria', 'Psicoses', 'Fácil', 'A', 'Diagnóstico', 'Ouvir vozes na ausência de um estímulo externo é classificado como quê?', 'Ilusão visual|Compulsão|Alucinação auditiva|Amnésia anterógrada', 2, 'Uma perceção sem estímulo externo correspondente é uma alucinação; as auditivas são comuns em psicoses.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241549790', 'Demonstração'),
('q-167', 'Psiquiatria', 'Delirium', 'Fácil', 'A', 'Diagnóstico', 'Que característica distingue mais o delirium de uma demência estável?', 'Perda gradual de memória ao longo de anos|Linguagem preservada|Idade superior a 65 anos|Início agudo com atenção flutuante', 3, 'O delirium surge de forma aguda, flutua e compromete sobretudo a atenção e o nível de consciência.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg103', 'Demonstração'),
('q-168', 'Psiquiatria', 'Álcool', 'Fácil', 'B', 'Prevenção', 'Qual é uma forma apropriada de iniciar rastreio de consumo nocivo de álcool?', 'Perguntas não julgadoras com instrumento validado|Assumir consumo pela aparência|Pedir apenas provas hepáticas|Evitar quantificar bebidas', 0, 'Uma abordagem não estigmatizante e instrumentos validados permitem identificar risco e orientar intervenção breve.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241599931', 'Demonstração'),
('q-169', 'Psiquiatria', 'Sono', 'Fácil', 'B', 'Prevenção', 'Qual é uma recomendação de higiene do sono para insónia?', 'Usar ecrãs luminosos na cama|Manter horário regular e reduzir estimulantes ao fim do dia|Dormir longas sestas diariamente|Tomar álcool para induzir sono', 1, 'Regularidade, controlo de estímulos e redução de cafeína e ecrãs são componentes comportamentais úteis.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-170', 'Psiquiatria', 'Perturbações neurocognitivas', 'Fácil', 'B', 'Diagnóstico', 'Declínio cognitivo progressivo que interfere com autonomia, sem flutuação aguda, sugere quê?', 'Delirium isolado|Ataque de pânico|Perturbação neurocognitiva major|Fobia específica', 2, 'O declínio adquirido, progressivo e funcionalmente relevante é compatível com perturbação neurocognitiva major.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng97', 'Demonstração'),
('q-171', 'Psiquiatria', 'Perturbação obsessivo-compulsiva', 'Fácil', 'B', 'Diagnóstico', 'Pensamentos intrusivos indesejados seguidos de rituais repetitivos para reduzir ansiedade sugerem quê?', 'Perturbação delirante|Delirium|Perturbação de conversão|Perturbação obsessivo-compulsiva', 3, 'Obsessões e compulsões reconhecidas como excessivas ou indesejadas caracterizam a perturbação obsessivo-compulsiva.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg31', 'Demonstração'),
('q-172', 'Psiquiatria', 'Ansiedade social', 'Fácil', 'B', 'Diagnóstico', 'Medo persistente de avaliação negativa em situações sociais, com evitamento, sugere quê?', 'Perturbação de ansiedade social|Agorafobia sem medo social|Esquizofrenia|Delirium', 0, 'O medo de escrutínio e humilhação que leva a evitamento é central na ansiedade social.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg159', 'Demonstração'),
('q-173', 'Psiquiatria', 'Perturbação bipolar', 'Fácil', 'A', 'Diagnóstico', 'Humor elevado, menor necessidade de sono, discurso acelerado e comportamento de risco sugerem que síndrome?', 'Episódio depressivo|Episódio maníaco|Delirium hipoativo|Perturbação de ansiedade generalizada', 1, 'Elevação ou irritabilidade do humor com energia aumentada e redução do sono é típica de mania.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg185', 'Demonstração'),
('q-174', 'Psiquiatria', 'Comportamento alimentar', 'Fácil', 'A', 'Diagnóstico', 'Restrição alimentar marcada, medo intenso de aumentar peso e baixo peso sugerem quê?', 'Perturbação de ingestão compulsiva|Delirium|Anorexia nervosa|Perturbação de pânico', 2, 'Restrição persistente com baixo peso e medo de ganho ponderal é compatível com anorexia nervosa.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng69', 'Demonstração'),
('q-175', 'Psiquiatria', 'Risco suicidário', 'Média', 'A', 'Gestão do doente', 'Uma pessoa com depressão admite pensamentos de morte, mas hesita em detalhar. Qual é a melhor abordagem?', 'Evitar o tema para não induzir ideias|Prometer segredo absoluto|Usar apenas uma escala e dar alta|Perguntar diretamente por intenção, plano, meios, fatores protetores e segurança', 3, 'Perguntas diretas não aumentam o risco e permitem uma avaliação clínica abrangente e um plano de segurança.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789240026629', 'Demonstração'),
('q-176', 'Psiquiatria', 'Psicofarmacologia', 'Média', 'B', 'Diagnóstico', 'Agitação, hiperreflexia, clónus, febre e diarreia após associação de fármacos serotoninérgicos sugerem quê?', 'Síndrome serotoninérgica|Síndrome neuroléptica maligna|Abstinência de nicotina|Delirium hipoativo', 0, 'Clónus e hiperreflexia com sinais autonómicos após exposição serotoninérgica são características desta síndrome.', 'Conteúdo demonstrativo ACE · NICE', 'https://bnf.nice.org.uk/', 'Demonstração'),
('q-177', 'Psiquiatria', 'Psicofarmacologia', 'Média', 'B', 'Diagnóstico', 'Rigidez generalizada, febre, alteração da consciência e creatina quinase elevada após antipsicótico sugerem quê?', 'Síndrome serotoninérgica típica|Síndrome neuroléptica maligna|Crise de ausência|Perturbação somática', 1, 'A síndrome neuroléptica maligna associa rigidez intensa, hipertermia e disfunção autonómica após bloqueio dopaminérgico.', 'Conteúdo demonstrativo ACE · NICE', 'https://bnf.nice.org.uk/', 'Demonstração'),
('q-178', 'Psiquiatria', 'Álcool', 'Média', 'A', 'Gestão do doente', 'Tremor, ansiedade, sudorese e taquicardia horas após cessar consumo intenso de álcool sugerem quê?', 'Intoxicação por opioides|Episódio depressivo|Síndrome de abstinência alcoólica|Demência', 2, 'A abstinência autonómica surge após redução abrupta; gravidade e risco de convulsão devem ser avaliados.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241549790', 'Demonstração'),
('q-179', 'Psiquiatria', 'Opioides', 'Média', 'A', 'Gestão do doente', 'Uma pessoa tem respiração lenta, miose e consciência reduzida após consumo de opioide. Qual é a prioridade?', 'Dar flumazenilo universalmente|Induzir vómito|Esperar acordar sem vigilância|Ventilar e administrar naloxona titulada', 3, 'A depressão respiratória é a ameaça imediata; suporte ventilatório e naloxona são fundamentais.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241548816', 'Demonstração'),
('q-180', 'Psiquiatria', 'Delirium', 'Média', 'A', 'Gestão do doente', 'Uma pessoa hospitalizada desenvolve delirium. Qual é a intervenção central?', 'Procurar e tratar causas, reorientar e reduzir fatores precipitantes|Iniciar contenção física de rotina|Administrar benzodiazepina em todos os casos|Mudar de quarto repetidamente', 0, 'O tratamento incide na causa e em medidas não farmacológicas; sedação é reservada a situações selecionadas de risco.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg103', 'Demonstração'),
('q-181', 'Psiquiatria', 'Psicofarmacologia', 'Média', 'B', 'Gestão do doente', 'Numa pessoa medicada com lítio, que monitorização é relevante?', 'Apenas hemoglobina anual|Níveis séricos, função renal, tiroide e interações|Nenhuma se estiver assintomática|Radiografia do tórax mensal', 1, 'O lítio tem margem terapêutica estreita e exige níveis, função renal e tiroideia e revisão de fármacos interagentes.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg185', 'Demonstração'),
('q-182', 'Psiquiatria', 'Saúde mental perinatal', 'Média', 'A', 'Diagnóstico', 'Semanas após o parto, uma mulher apresenta tristeza persistente, culpa, anedonia e dificuldade de vinculação. Qual é a hipótese?', 'Baby blues fisiológico obrigatório|Psicose puerperal sem psicose|Depressão pós-parto|Delirium por definição', 2, 'Sintomas depressivos persistentes e incapacitantes além da labilidade transitória exigem avaliação e apoio.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg192', 'Demonstração'),
('q-183', 'Psiquiatria', 'Neurodesenvolvimento', 'Média', 'B', 'Diagnóstico', 'Desatenção e hiperatividade presentes em mais de um contexto desde a infância, com prejuízo funcional, sugerem quê?', 'Perturbação bipolar obrigatória|Delirium|Demência frontotemporal|Perturbação de hiperatividade e défice de atenção', 3, 'O padrão persistente, precoce e transversal a contextos é necessário para considerar PHDA.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng87', 'Demonstração'),
('q-184', 'Psiquiatria', 'Neurodesenvolvimento', 'Média', 'B', 'Diagnóstico', 'Dificuldades persistentes de comunicação social e comportamentos restritos desde o desenvolvimento precoce sugerem quê?', 'Perturbação do espetro do autismo|Perturbação de pânico|Delirium|Depressão melancólica', 0, 'O diagnóstico considera comunicação social, padrões restritos e história do desenvolvimento, com avaliação multidisciplinar.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg128', 'Demonstração'),
('q-185', 'Psiquiatria', 'Trauma', 'Média', 'B', 'Diagnóstico', 'Após evento traumático, uma pessoa apresenta intrusões, evitamento, hipervigilância e alterações de humor por mais de um mês. Qual é a hipótese?', 'Reação aguda transitória obrigatória|Perturbação de stress pós-traumático|Perturbação obsessivo-compulsiva|Delirium', 1, 'A persistência de grupos de sintomas traumáticos além da fase aguda é compatível com PSPT.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng116', 'Demonstração'),
('q-186', 'Psiquiatria', 'Comportamento alimentar', 'Média', 'B', 'Diagnóstico', 'Episódios de ingestão compulsiva seguidos de vómito autoinduzido, com peso frequentemente normal, sugerem quê?', 'Anorexia nervosa restritiva obrigatória|Delirium|Bulimia nervosa|Perturbação de pânico', 2, 'Compulsões recorrentes e comportamentos compensatórios inadequados são centrais na bulimia nervosa.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng69', 'Demonstração'),
('q-187', 'Psiquiatria', 'Capacidade de decisão', 'Média', 'A', 'Diagnóstico', 'Ao avaliar capacidade para uma decisão clínica concreta, o que deve ser verificado?', 'Concordar obrigatoriamente com o médico|Ter qualquer diagnóstico psiquiátrico|Obter uma pontuação cognitiva perfeita|Compreender, reter, ponderar e comunicar a decisão com apoio adequado', 3, 'Capacidade é específica à decisão e ao momento e deve ser apoiada, não inferida apenas de diagnóstico ou desacordo.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241516754', 'Demonstração'),
('q-188', 'Psiquiatria', 'Catatonia', 'Difícil', 'B', 'Diagnóstico', 'Mutismo, imobilidade, negativismo e posturas mantidas numa pessoa com doença psiquiátrica ou médica sugerem quê?', 'Catatonia|Acatisia|Ataque de pânico|Discinesia tardia', 0, 'A catatonia é uma síndrome psicomotora potencialmente grave e pode ocorrer em doenças do humor, psicose ou causas médicas.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance', 'Demonstração'),
('q-189', 'Psiquiatria', 'Álcool', 'Difícil', 'A', 'Gestão do doente', 'Dois dias após cessar álcool, uma pessoa apresenta confusão, alucinações, febre, hipertensão e tremor intenso. Qual é a hipótese?', 'Intoxicação simples por álcool|Delirium tremens|Episódio depressivo|Demência estável', 1, 'Delirium com hiperatividade autonómica na abstinência é uma emergência que requer benzodiazepina e suporte monitorizado.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241549790', 'Demonstração'),
('q-190', 'Psiquiatria', 'Psicofarmacologia', 'Difícil', 'A', 'Gestão do doente', 'Perante suspeita de síndrome neuroléptica maligna, qual é uma medida imediata?', 'Aumentar a dose do antipsicótico|Dar alta com antipirético|Suspender o fármaco causal e iniciar suporte intensivo|Iniciar exercício intenso', 2, 'A suspensão do bloqueador dopaminérgico, suporte de órgão e tratamento especializado não devem ser atrasados.', 'Conteúdo demonstrativo ACE · NICE', 'https://bnf.nice.org.uk/', 'Demonstração'),
('q-191', 'Psiquiatria', 'Psicofarmacologia', 'Difícil', 'A', 'Diagnóstico', 'Uma pessoa medicada com lítio desenvolve vómitos, ataxia, tremor grosseiro e confusão após desidratação. Qual é a preocupação?', 'Síndrome de abstinência alcoólica|Acatisia|Hipomania|Toxicidade por lítio', 3, 'Desidratação e interações podem elevar lítio; sinais neurológicos requerem doseamento e tratamento urgente.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg185', 'Demonstração'),
('q-192', 'Psiquiatria', 'Psicofarmacologia', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa que iniciou clozapina apresenta febre e odinofagia. Qual é a ação apropriada?', 'Avaliar urgentemente neutrófilos e seguir protocolo de clozapina|Reassurar sem análises|Duplicar a dose|Administrar vacina viva', 0, 'Febre ou sintomas de infeção podem indicar neutropenia grave e exigem hemograma e atuação segundo protocolo.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg178', 'Demonstração'),
('q-193', 'Psiquiatria', 'Psicofarmacologia', 'Difícil', 'A', 'Gestão do doente', 'Qual é a primeira medida perante síndrome serotoninérgica clinicamente relevante?', 'Adicionar outro antidepressivo|Suspender agentes serotoninérgicos e prestar suporte|Administrar antipsicótico depot|Ignorar hipertermia', 1, 'Remoção do agente, suporte, controlo de agitação e hipertermia e escalada conforme gravidade são fundamentais.', 'Conteúdo demonstrativo ACE · NICE', 'https://bnf.nice.org.uk/', 'Demonstração'),
('q-194', 'Psiquiatria', 'Saúde mental perinatal', 'Difícil', 'A', 'Gestão do doente', 'Dias após o parto, uma mulher apresenta insónia total, discurso desorganizado e crenças delirantes sobre o bebé. Qual é a resposta?', 'Rever em consulta dentro de um mês|Tratar como baby blues|Avaliação psiquiátrica urgente e proteção da mãe e do bebé|Deixar mãe e bebé sem apoio', 2, 'Psicose pós-parto é uma emergência com risco elevado e necessita de avaliação especializada imediata.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg192', 'Demonstração'),
('q-195', 'Psiquiatria', 'Comportamento alimentar', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa com anorexia grave inicia nutrição após jejum prolongado. Que risco deve ser prevenido e monitorizado?', 'Hipervitaminose C|Síndrome serotoninérgica|Abstinência de nicotina|Síndrome de realimentação', 3, 'A realimentação pode causar alterações de fósforo, potássio, magnésio e fluidos, exigindo início e vigilância planeados.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg32', 'Demonstração'),
('q-196', 'Psiquiatria', 'Perturbação bipolar', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa em mania grave está agitada, sem dormir e coloca terceiros em risco. Qual é a prioridade?', 'Ambiente seguro, desescalada e tratamento urgente da mania|Psicoterapia mensal como única medida|Prescrever antidepressivo isolado|Dar alta sem plano', 0, 'A segurança e a redução rápida de agitação e mania requerem intervenção urgente e avaliação de internamento.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg185', 'Demonstração'),
('q-197', 'Psiquiatria', 'Primeiro episódio psicótico', 'Difícil', 'A', 'Diagnóstico', 'Num primeiro episódio psicótico, qual é um princípio essencial da avaliação?', 'Assumir esquizofrenia sem exame|Pesquisar substâncias, causas médicas, risco e história temporal|Evitar falar com familiares mesmo com consentimento|Pedir apenas teste de personalidade', 1, 'Psicose pode ter causas primárias, tóxicas ou médicas; avaliação inicial ampla orienta tratamento seguro.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg178', 'Demonstração'),
('q-198', 'Psiquiatria', 'Álcool', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa com consumo crónico de álcool apresenta confusão, ataxia e alterações oculomotoras. O que deve ser administrado sem atraso?', 'Ácido fólico como única medida|Naloxona|Tiamina, idealmente antes de glicose quando possível|Lítio', 2, 'A tríade sugere encefalopatia de Wernicke; tiamina parentérica deve ser administrada rapidamente sem atrasar glicose urgente.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/cg100', 'Demonstração'),
('q-199', 'Psiquiatria', 'Agitação', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa muito agitada chega à urgência. Qual é a primeira abordagem, se houver condições de segurança?', 'Conter mecanicamente sem interação|Discutir para provar que está errada|Deixar objetos perigosos acessíveis|Reduzir estímulos e tentar desescalada verbal com equipa preparada', 3, 'A desescalada e o ambiente seguro são preferidos; medidas restritivas devem ser proporcionais, monitorizadas e de último recurso.', 'Conteúdo demonstrativo ACE · NICE', 'https://www.nice.org.uk/guidance/ng10', 'Demonstração'),
('q-200', 'Psiquiatria', 'Risco de violência', 'Difícil', 'A', 'Gestão do doente', 'Uma pessoa com psicose refere vozes imperativas para ferir alguém e acesso a uma arma. Qual é a resposta?', 'Avaliação urgente do risco, proteção de potenciais vítimas e contenção clínica segura|Manter segredo absoluto e dar alta|Marcar psicoterapia em seis meses|Ignorar por serem apenas sintomas', 0, 'Conteúdo imperativo, intenção e acesso a meios exigem intervenção urgente e medidas proporcionais de segurança.', 'Conteúdo demonstrativo ACE · WHO', 'https://www.who.int/publications/i/item/9789241549790', 'Demonstração');
